<?xml version="1.0" encoding="utf-8"?>
<androidx.coordinatorlayout.widget.CoordinatorLayout xmlns:android="http://schemas.android.com/apk/res/android"
 xmlns:app="http://schemas.android.com/apk/res-auto"
 xmlns:tools="http://schemas.android.com/tools"
 android:id="@+id/main_broadcast_layout"
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 android:background="@android:color/black"
 tools:context=".MainActivity">

 <!-- App Bar / Toolbar -->
 <com.google.android.material.appbar.AppBarLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:theme="@style/ThemeOverlay.Material3.Dark.ActionBar">

 <com.google.android.material.appbar.MaterialToolbar
 android:id="@+id/toolbar_main"
 android:layout_width="match_parent"
 android:layout_height="?attr/actionBarSize"
 android:background="@color/spu_dark_blue"
 app:title="SPU Cricket Live"
 app:titleTextColor="@color/white" />
 </com.google.android.material.appbar.AppBarLayout>

 <!-- Camera Preview (Live Match Feed) -->
 <androidx.camera.view.PreviewView
 android:id="@+id/camera_preview_broadcast"
 android:layout_width="0dp"
 android:layout_height="0dp"
 app:layout_constraintTop_toBottomOf="@id/toolbar_main"
 app:layout_constraintStart_toStartOf="parent"
 app:layout_constraintEnd_toEndOf="parent"
 app:layout_constraintBottom_toBottomOf="parent" />

 <!-- Scoreboard Overlay -->
 <FrameLayout
 android:id="@+id/scoreboard_overlay_container"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 app:layout_constraintBottom_toBottomOf="parent"
 app:layout_constraintStart_toStartOf="parent"
 app:layout_constraintEnd_toEndOf="parent"
 android:background="#CC000000"
 android:padding="8dp">

 <include
 android:id="@+id/cricket_score_panel_broadcast"
 layout="@layout/cricket_score_panel_simplified"
 android:layout_width="match_parent"
 android:layout_height="wrap_content" />

 </FrameLayout>

 <!-- Minimal Controls / Channel Logo (Optional) -->
 <ImageView
 android:id="@+id/channel_logo_overlay"
 android:layout_width="70dp"
 android:layout_height="35dp"
 android:src="@drawable/logo"
 android:layout_margin="16dp"
 app:layout_constraintTop_toTopOf="parent"
 app:layout_constraintEnd_toEndOf="parent"
 android:alpha="0.8"
 android:contentDescription="SPU Logo" />

 <!-- AI Tracking Status Overlay -->
 <com.google.android.material.card.MaterialCardView
 android:id="@+id/ai_status_overlay"
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:layout_margin="16dp"
 app:cardBackgroundColor="#A0000000"
 app:cardCornerRadius="8dp"
 app:contentPadding="8dp"
 app:layout_constraintTop_toTopOf="parent"
 app:layout_constraintEnd_toEndOf="parent">

 <LinearLayout
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:orientation="vertical"
 android:gravity="center_horizontal">

 <TextView
 android:id="@+id/text_ai_status_title"
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:text="AI Tracking"
 android:textColor="@color/spu_gold"
 android:textSize="14sp"
 android:textStyle="bold" />

 <TextView
 android:id="@+id/text_ai_status_message"
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:text="Initializing..."
 android:textColor="@color/white"
 android:textSize="12sp" />
 </LinearLayout>
 </com.google.android.material.card.MaterialCardView>

 <!-- Bottom Control Sheet -->
 <com.google.android.material.card.MaterialCardView
 android:id="@+id/bottom_control_sheet"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 app:cardBackgroundColor="@color/spu_dark_blue_transparent"
 app:cardCornerRadius="16dp"
 app:cardElevation="8dp"
 app:layout_constraintBottom_toBottomOf="parent"
 app:layout_constraintStart_toStartOf="parent"
 app:layout_constraintEnd_toEndOf="parent"
 android:layout_marginBottom="80dp">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="vertical"
 android:padding="16dp">

 <TextView
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:text="AI Tracking Controls"
 android:textColor="@color/spu_gold"
 android:textSize="16sp"
 android:textStyle="bold"
 android:layout_marginBottom="8dp" />

 <com.google.android.material.button.MaterialButtonToggleGroup
 android:id="@+id/toggle_ai_tracking_group"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 app:singleSelection="false"
 app:selectionRequired="false"
 android:layout_marginBottom="8dp">

 <Button
 android:id="@+id/btn_toggle_ball_tracking"
 style="?attr/materialButtonOutlinedStyle"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="Ball"
 android:textColor="@color/white"
 app:iconTint="@color/white"
 app:strokeColor="@color/spu_gold"
 app:icon="@drawable/ic_ball_tracking" />

 <Button
 android:id="@+id/btn_toggle_player_tracking"
 style="?attr/materialButtonOutlinedStyle"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="Player"
 android:textColor="@color/white"
 app:iconTint="@color/white"
 app:strokeColor="@color/spu_gold"
 app:icon="@drawable/ic_player_tracking" />

 <Button
 android:id="@+id/btn_toggle_pose_estimation"
 style="?attr/materialButtonOutlinedStyle"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="Pose"
 android:textColor="@color/white"
 app:iconTint="@color/white"
 app:strokeColor="@color/spu_gold"
 app:icon="@drawable/ic_pose_estimation" />
 </com.google.android.material.button.MaterialButtonToggleGroup>

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="horizontal">

 <com.google.android.material.button.MaterialButton
 android:id="@+id/button_start_recording_main"
 style="@style/Widget.Material3.Button.ElevatedButton"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:text="Record"
 app:icon="@android:drawable/ic_media_play"
 app:iconTint="@color/white"
 android:textColor="@color/white"
 app:backgroundTint="@color/spu_blue"
 android:layout_weight="1"
 android:layout_marginEnd="8dp" />

 <com.google.android.material.button.MaterialButton
 android:id="@+id/button_quick_wicket_main"
 style="@style/Widget.Material3.Button.TonalButton"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:text="Wicket"
 app:iconTint="@color/white"
 android:textColor="@color/white"
 app:backgroundTint="@color/spu_accent_red"
 app:icon="@android:drawable/ic_menu_delete"
 android:layout_weight="1" />
 </LinearLayout>
 </LinearLayout>
 </com.google.android.material.card.MaterialCardView>

 <!-- Floating Action Button for main actions -->
 <com.google.android.material.floatingactionbutton.FloatingActionButton
 android:id="@+id/fab_main_action"
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:layout_margin="16dp"
 android:contentDescription="Main Action"
 android:src="@android:drawable/ic_input_add"
 app:backgroundTint="@color/spu_gold"
 app:tint="@color/spu_dark_blue"
 app:layout_anchor="@id/bottom_control_sheet"
 app:layout_anchorGravity="top|end" />

</androidx.coordinatorlayout.widget.CoordinatorLayout>

