```xml:app/src/main/res/layout/item_top_player.xml
<?xml version="1.0" encoding="utf-8"?>
<com.google.android.material.card.MaterialCardView xmlns:android="http://schemas.android.com/apk/res/android"
 xmlns:app="http://schemas.android.com/apk/res-auto"
 xmlns:tools="http://schemas.android.com/tools"
 android:layout_width="140dp"
 android:layout_height="wrap_content"
 android:layout_margin="4dp"
 app:cardCornerRadius="16dp"
 app:cardElevation="1dp">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="vertical"
 android:padding="12dp">

 <com.google.android.material.imageview.ShapeableImageView
 android:id="@+id/player_image"
 android:layout_width="80dp"
 android:layout_height="80dp"
 android:layout_gravity="center_horizontal"
 android:background="@drawable/circle_background"
 android:padding="2dp"
 android:src="@android:drawable/ic_menu_gallery"
 app:shapeAppearanceOverlay="@style/ShapeAppearance.Material3.Corner.Full"
 android:contentDescription="Player photo" />

 <com.google.android.material.textview.MaterialTextView
 android:id="@+id/player_name"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginTop="8dp"
 android:ellipsize="end"
 android:gravity="center"
 android:maxLines="1"
 android:textAppearance="@style/TextAppearance.Material3.TitleSmall"
 tools:text="M.S. Dhoni" />

 <com.google.android.material.textview.MaterialTextView
 android:id="@+id/player_role"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:ellipsize="end"
 android:gravity="center"
 android:maxLines="1"
 android:textAppearance="@style/TextAppearance.Material3.BodySmall"
 tools:text="Wicket Keeper" />

 <com.google.android.material.card.MaterialCardView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginTop="8dp"
 app:cardBackgroundColor="@color/spu_blue"
 app:cardCornerRadius="8dp"
 app:cardElevation="0dp">

 <com.google.android.material.textview.MaterialTextView
 android:id="@+id/player_stat"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:gravity="center"
 android:padding="4dp"
 android:textColor="@color/white"
 android:textAppearance="@style/TextAppearance.Material3.LabelMedium"
 tools:text="85 Runs (58 balls)" />
 </com.google.android.material.card.MaterialCardView>
 </LinearLayout>
</com.google.android.material.card.MaterialCardView>
```
