```xml:app/src/main/res/layout/activity_dashboard.xml
<?xml version="1.0" encoding="utf-8"?>
<androidx.coordinatorlayout.widget.CoordinatorLayout xmlns:android="http://schemas.android.com/apk/res/android"
 xmlns:app="http://schemas.android.com/apk/res-auto"
 xmlns:tools="http://schemas.android.com/tools"
 android:id="@+id/dashboard_coordinator_layout"
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 tools:context=".DashboardActivity">

 <com.google.android.material.appbar.AppBarLayout
 android:id="@+id/appbar_layout"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:theme="@style/ThemeOverlay.Material3.Dark.ActionBar">

 <com.google.android.material.appbar.MaterialToolbar
 android:id="@+id/toolbar"
 android:layout_width="match_parent"
 android:layout_height="?attr/actionBarSize"
 android:background="?attr/colorPrimary"
 app:popupTheme="@style/ThemeOverlay.Material3.Light" />

 </com.google.android.material.appbar.AppBarLayout>

 <androidx.core.widget.NestedScrollView
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 android:fillViewport="true"
 app:layout_behavior="@string/appbar_scrolling_view_behavior">

 <androidx.constraintlayout.widget.ConstraintLayout
 android:layout_width="match_parent"
 android:layout_height="match_parent">

 <!-- Current/Next Match Banner Card -->
 <com.google.android.material.card.MaterialCardView
 android:id="@+id/match_banner_card"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_margin="16dp"
 app:cardCornerRadius="16dp"
 app:cardElevation="2dp"
 app:cardBackgroundColor="@color/spu_blue"
 app:layout_constraintTop_toTopOf="parent">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="vertical"
 android:padding="16dp">

 <com.google.android.material.textview.MaterialTextView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="UPCOMING MATCH"
 android:textColor="@color/white"
 android:textAppearance="@style/TextAppearance.Material3.LabelLarge" />

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:gravity="center_vertical"
 android:orientation="horizontal"
 android:paddingTop="16dp"
 android:paddingBottom="16dp">

 <LinearLayout
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="2"
 android:gravity="center"
 android:orientation="vertical">

 <ImageView
 android:id="@+id/home_team_logo"
 android:layout_width="64dp"
 android:layout_height="64dp"
 android:background="@drawable/circle_background"
 android:padding="12dp"
 android:src="@android:drawable/ic_menu_myplaces" />

 <com.google.android.material.textview.MaterialTextView
 android:id="@+id/home_team_name"
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:layout_marginTop="4dp"
 android:text="SPU"
 android:textColor="@color/white"
 android:textAppearance="@style/TextAppearance.Material3.TitleMedium" />
 </LinearLayout>

 <com.google.android.material.textview.MaterialTextView
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:gravity="center"
 android:text="VS"
 android:textColor="@color/spu_gold"
 android:textAppearance="@style/TextAppearance.Material3.HeadlineSmall" />

 <LinearLayout
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="2"
 android:gravity="center"
 android:orientation="vertical">

 <ImageView
 android:id="@+id/away_team_logo"
 android:layout_width="64dp"
 android:layout_height="64dp"
 android:background="@drawable/circle_background"
 android:padding="12dp"
 android:src="@android:drawable/ic_menu_myplaces" />

 <com.google.android.material.textview.MaterialTextView
 android:id="@+id/away_team_name"
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:layout_marginTop="4dp"
 android:text="Opponents"
 android:textColor="@color/white"
 android:textAppearance="@style/TextAppearance.Material3.TitleMedium" />
 </LinearLayout>
 </LinearLayout>

 <com.google.android.material.textview.MaterialTextView
 android:id="@+id/match_date_time"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:drawableStart="@android:drawable/ic_menu_my_calendar"
 android:drawablePadding="8dp"
 android:gravity="center"
 android:text="Sunday, June 12 • 2:00 PM"
 android:textColor="@color/white"
 android:textAppearance="@style/TextAppearance.Material3.BodyLarge" />

 <com.google.android.material.button.MaterialButton
 android:id="@+id/button_start_match"
 style="@style/Widget.Material3.Button.OutlinedButton"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginTop="8dp"
 android:text="Start Match"
 android:textColor="@color/spu_gold"
 app:strokeColor="@color/spu_gold" />
 </LinearLayout>
 </com.google.android.material.card.MaterialCardView>

 <!-- Quick Actions Grid -->
 <com.google.android.material.textview.MaterialTextView
 android:id="@+id/quick_actions_title"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginStart="16dp"
 android:layout_marginTop="16dp"
 android:layout_marginEnd="16dp"
 android:text="Quick Actions"
 android:textAppearance="@style/TextAppearance.Material3.TitleLarge"
 app:layout_constraintTop_toBottomOf="@+id/match_banner_card" />

 <LinearLayout
 android:id="@+id/quick_actions_grid"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginStart="8dp"
 android:layout_marginEnd="8dp"
 android:orientation="vertical"
 app:layout_constraintTop_toBottomOf="@+id/quick_actions_title">

 <!-- First row -->
 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="horizontal"
 android:weightSum="2">

 <!-- Team Management -->
 <com.google.android.material.card.MaterialCardView
 android:id="@+id/card_team_management"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_margin="8dp"
 android:layout_weight="1"
 android:clickable="true"
 android:focusable="true"
 app:cardCornerRadius="16dp"
 app:cardElevation="2dp"
 app:cardBackgroundColor="@color/spu_blue"
 app:strokeWidth="0dp">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:gravity="center"
 android:orientation="vertical"
 android:padding="16dp">

 <ImageView
 android:layout_width="48dp"
 android:layout_height="48dp"
 android:src="@drawable/ic_menu_gallery"
 app:tint="@color/spu_gold" />

 <com.google.android.material.textview.MaterialTextView
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:layout_marginTop="8dp"
 android:text="Team Management"
 android:textColor="@color/spu_gold"
 android:textAppearance="@style/TextAppearance.Material3.TitleSmall" />
 </LinearLayout>
 </com.google.android.material.card.MaterialCardView>

 <!-- Player Registration -->
 <com.google.android.material.card.MaterialCardView
 android:id="@+id/card_player_registration"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_margin="8dp"
 android:layout_weight="1"
 android:clickable="true"
 android:focusable="true"
 app:cardCornerRadius="16dp"
 app:cardElevation="2dp"
 app:cardBackgroundColor="@color/spu_blue"
 app:strokeWidth="0dp">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:gravity="center"
 android:orientation="vertical"
 android:padding="16dp">

 <ImageView
 android:layout_width="48dp"
 android:layout_height="48dp"
 android:src="@drawable/ic_menu_camera"
 app:tint="@color/spu_gold" />

 <com.google.android.material.textview.MaterialTextView
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:layout_marginTop="8dp"
 android:text="Register Players"
 android:textColor="@color/spu_gold"
 android:textAppearance="@style/TextAppearance.Material3.TitleSmall" />
 </LinearLayout>
 </com.google.android.material.card.MaterialCardView>
 </LinearLayout>

 <!-- Second row -->
 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="horizontal"
 android:weightSum="2">

 <!-- Analytics -->
 <com.google.android.material.card.MaterialCardView
 android:id="@+id/card_analytics"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_margin="8dp"
 android:layout_weight="1"
 android:clickable="true"
 android:focusable="true"
 app:cardCornerRadius="16dp"
 app:cardElevation="2dp"
 app:cardBackgroundColor="@color/spu_blue"
 app:strokeWidth="0dp">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:gravity="center"
 android:orientation="vertical"
 android:padding="16dp">

 <ImageView
 android:layout_width="48dp"
 android:layout_height="48dp"
 android:src="@android:drawable/ic_menu_sort_by_size"
 app:tint="@color/spu_gold" />

 <com.google.android.material.textview.MaterialTextView
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:layout_marginTop="8dp"
 android:text="Analytics"
 android:textColor="@color/spu_gold"
 android:textAppearance="@style/TextAppearance.Material3.TitleSmall" />
 </LinearLayout>
 </com.google.android.material.card.MaterialCardView>

 <!-- Match History -->
 <com.google.android.material.card.MaterialCardView
 android:id="@+id/card_match_history"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_margin="8dp"
 android:layout_weight="1"
 android:clickable="true"
 android:focusable="true"
 app:cardCornerRadius="16dp"
 app:cardElevation="2dp"
 app:cardBackgroundColor="@color/spu_blue"
 app:strokeWidth="0dp">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:gravity="center"
 android:orientation="vertical"
 android:padding="16dp">

 <ImageView
 android:layout_width="48dp"
 android:layout_height="48dp"
 android:src="@android:drawable/ic_menu_recent_history"
 app:tint="@color/spu_gold" />

 <com.google.android.material.textview.MaterialTextView
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:layout_marginTop="8dp"
 android:text="Match History"
 android:textColor="@color/spu_gold"
 android:textAppearance="@style/TextAppearance.Material3.TitleSmall" />
 </LinearLayout>
 </com.google.android.material.card.MaterialCardView>
 </LinearLayout>

 <!-- Third row -->
 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="horizontal"
 android:weightSum="2">

 <!-- Pitch Vision -->
 <com.google.android.material.card.MaterialCardView
 android:id="@+id/card_pitch_vision"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_margin="8dp"
 android:layout_weight="1"
 android:clickable="true"
 android:focusable="true"
 app:cardCornerRadius="16dp"
 app:cardElevation="2dp"
 app:cardBackgroundColor="@color/spu_blue"
 app:strokeWidth="0dp">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:gravity="center"
 android:orientation="vertical"
 android:padding="16dp">

 <ImageView
 android:layout_width="48dp"
 android:layout_height="48dp"
 android:src="@drawable/ic_analyze"
 app:tint="@color/spu_gold" />

 <com.google.android.material.textview.MaterialTextView
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:layout_marginTop="8dp"
 android:text="Pitch Vision"
 android:textColor="@color/spu_gold"
 android:textAppearance="@style/TextAppearance.Material3.TitleSmall" />
 </LinearLayout>
 </com.google.android.material.card.MaterialCardView>

 <!-- Empty card or another feature -->
 <com.google.android.material.card.MaterialCardView
 android:id="@+id/card_settings"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_margin="8dp"
 android:layout_weight="1"
 android:clickable="true"
 android:focusable="true"
 app:cardCornerRadius="16dp"
 app:cardElevation="2dp"
 app:cardBackgroundColor="@color/spu_blue"
 app:strokeWidth="0dp">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:gravity="center"
 android:orientation="vertical"
 android:padding="16dp">

 <ImageView
 android:layout_width="48dp"
 android:layout_height="48dp"
 android:src="@drawable/ic_menu_manage"
 app:tint="@color/spu_gold" />

 <com.google.android.material.textview.MaterialTextView
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:layout_marginTop="8dp"
 android:text="Settings"
 android:textColor="@color/spu_gold"
 android:textAppearance="@style/TextAppearance.Material3.TitleSmall" />
 </LinearLayout>
 </com.google.android.material.card.MaterialCardView>
 </LinearLayout>
 </LinearLayout>

 <!-- Player Stats Section -->
 <com.google.android.material.textview.MaterialTextView
 android:id="@+id/player_stats_title"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginStart="16dp"
 android:layout_marginTop="16dp"
 android:layout_marginEnd="16dp"
 android:text="Top Performers"
 android:textAppearance="@style/TextAppearance.Material3.TitleLarge"
 app:layout_constraintTop_toBottomOf="@+id/quick_actions_grid" />

 <androidx.recyclerview.widget.RecyclerView
 android:id="@+id/top_players_recycler"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:clipToPadding="false"
 android:orientation="horizontal"
 android:padding="8dp"
 app:layoutManager="androidx.recyclerview.widget.LinearLayoutManager"
 app:layout_constraintTop_toBottomOf="@+id/player_stats_title"
 tools:listitem="@layout/item_top_player" />

 <!-- Recent Activity Section -->
 <com.google.android.material.textview.MaterialTextView
 android:id="@+id/recent_activity_title"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginStart="16dp"
 android:layout_marginTop="16dp"
 android:layout_marginEnd="16dp"
 android:text="Recent Activity"
 android:textAppearance="@style/TextAppearance.Material3.TitleLarge"
 app:layout_constraintTop_toBottomOf="@+id/top_players_recycler" />

 <androidx.recyclerview.widget.RecyclerView
 android:id="@+id/recent_activity_recycler"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginStart="16dp"
 android:layout_marginEnd="16dp"
 android:layout_marginBottom="16dp"
 app:layoutManager="androidx.recyclerview.widget.LinearLayoutManager"
 app:layout_constraintTop_toBottomOf="@+id/recent_activity_title"
 tools:listitem="@layout/item_recent_activity" />

 </androidx.constraintlayout.widget.ConstraintLayout>
 </androidx.core.widget.NestedScrollView>

 <com.google.android.material.floatingactionbutton.ExtendedFloatingActionButton
 android:id="@+id/fab_new_match"
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:layout_gravity="bottom|end"
 android:layout_margin="16dp"
 android:contentDescription="Create new match"
 android:text="New Match"
 app:icon="@android:drawable/ic_input_add"
 app:backgroundTint="@color/spu_gold"
 app:iconTint="@color/spu_blue"
 app:iconSize="24dp" />

</androidx.coordinatorlayout.widget.CoordinatorLayout>

```
</file_contents>


