```xml:app/src/main/res/layout/activity_pitch_vision.xml
<?xml version="1.0" encoding="utf-8"?>
<androidx.coordinatorlayout.widget.CoordinatorLayout xmlns:android="http://schemas.android.com/apk/res/android"
 xmlns:app="http://schemas.android.com/apk/res-auto"
 xmlns:tools="http://schemas.android.com/tools"
 android:id="@+id/coordinator_layout"
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 android:background="@color/spu_background"
 tools:context=".PitchVisionActivity">

 <com.google.android.material.appbar.AppBarLayout
 android:id="@+id/appbar_layout"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:theme="@style/ThemeOverlay.Material3.Dark.ActionBar">

 <com.google.android.material.appbar.MaterialToolbar
 android:id="@+id/toolbar"
 android:layout_width="match_parent"
 android:layout_height="?attr/actionBarSize"
 android:background="?attr/colorPrimary"
 app:popupTheme="@style/ThemeOverlay.Material3.Light"
 app:title="Pitch Vision Analysis" />
 </com.google.android.material.appbar.AppBarLayout>

 <androidx.core.widget.NestedScrollView
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 app:layout_behavior="@string/appbar_scrolling_view_behavior">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="vertical"
 android:padding="16dp">

 <!-- Camera Preview -->
 <com.google.android.material.card.MaterialCardView
 android:layout_width="match_parent"
 android:layout_height="260dp"
 android:layout_marginBottom="16dp"
 app:cardCornerRadius="16dp"
 app:cardElevation="4dp">

 <FrameLayout
 android:layout_width="match_parent"
 android:layout_height="match_parent">

 <androidx.camera.view.PreviewView
 android:id="@+id/camera_preview"
 android:layout_width="match_parent"
 android:layout_height="match_parent" />

 <TextView
 android:id="@+id/text_status"
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:layout_gravity="top|center_horizontal"
 android:layout_margin="8dp"
 android:background="@drawable/rounded_status_bg"
 android:paddingHorizontal="16dp"
 android:paddingVertical="8dp"
 android:text="Point camera at cricket pitch"
 android:textColor="@color/white"
 android:textSize="14sp" />

 <ProgressBar
 android:id="@+id/progress_calibration"
 style="?android:attr/progressBarStyle"
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:layout_gravity="center"
 android:visibility="gone" />
 </FrameLayout>
 </com.google.android.material.card.MaterialCardView>

 <!-- Control Buttons -->
 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginBottom="16dp"
 android:orientation="horizontal">

 <com.google.android.material.button.MaterialButton
 android:id="@+id/btn_calibrate"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_marginEnd="8dp"
 android:layout_weight="1"
 android:text="Calibrate"
 app:backgroundTint="@color/spu_blue"
 app:icon="@drawable/ic_calibrate" />

 <com.google.android.material.button.MaterialButton
 android:id="@+id/btn_analyze"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_marginStart="8dp"
 android:layout_weight="1"
 android:text="Start Analysis"
 app:backgroundTint="@color/spu_success"
 app:icon="@drawable/ic_analyze" />
 </LinearLayout>

 <!-- Result Card -->
 <com.google.android.material.card.MaterialCardView
 android:id="@+id/card_results"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginBottom="16dp"
 app:cardCornerRadius="16dp"
 app:cardElevation="4dp">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="vertical"
 android:padding="16dp">

 <TextView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Pitch Analysis Results"
 android:textAppearance="@style/TextAppearance.Material3.TitleMedium"
 android:textColor="@color/spu_dark_blue" />

 <View
 android:layout_width="match_parent"
 android:layout_height="1dp"
 android:layout_marginVertical="8dp"
 android:background="@color/spu_light_gray" />

 <com.finedine.spucricketclub.ui.PitchHeatmapView
 android:id="@+id/pitch_heatmap_view"
 android:layout_width="match_parent"
 android:layout_height="150dp"
 android:layout_marginVertical="8dp" />

 <LinearLayout
 android:id="@+id/container_pitch_stats"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="vertical">

 <!-- Pitch Type -->
 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginVertical="4dp"
 android:orientation="horizontal">

 <TextView
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="Pitch Type:"
 android:textAppearance="@style/TextAppearance.Material3.BodyMedium"
 android:textColor="@color/dark_gray" />

 <TextView
 android:id="@+id/text_pitch_type"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="Loading..."
 android:textAppearance="@style/TextAppearance.Material3.BodyMedium"
 android:textColor="@color/spu_gold"
 android:textStyle="bold" />
 </LinearLayout>

 <!-- Grass Coverage -->
 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginVertical="4dp"
 android:orientation="horizontal">

 <TextView
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="Grass Coverage:"
 android:textAppearance="@style/TextAppearance.Material3.BodyMedium"
 android:textColor="@color/dark_gray" />

 <TextView
 android:id="@+id/text_grass_coverage"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="0.0%"
 android:textAppearance="@style/TextAppearance.Material3.BodyMedium"
 android:textColor="@color/spu_success" />
 </LinearLayout>

 <!-- Cracks -->
 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginVertical="4dp"
 android:orientation="horizontal">

 <TextView
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="Cracks/Dryness:"
 android:textAppearance="@style/TextAppearance.Material3.BodyMedium"
 android:textColor="@color/dark_gray" />

 <TextView
 android:id="@+id/text_cracks"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="0.0%"
 android:textAppearance="@style/TextAppearance.Material3.BodyMedium"
 android:textColor="@color/spu_danger" />
 </LinearLayout>

 <!-- Moisture -->
 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginVertical="4dp"
 android:orientation="horizontal">

 <TextView
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="Moisture Level:"
 android:textAppearance="@style/TextAppearance.Material3.BodyMedium"
 android:textColor="@color/dark_gray" />

 <TextView
 android:id="@+id/text_moisture"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="0.0%"
 android:textAppearance="@style/TextAppearance.Material3.BodyMedium"
 android:textColor="@color/spu_blue" />
 </LinearLayout>

 <View
 android:layout_width="match_parent"
 android:layout_height="1dp"
 android:layout_marginVertical="8dp"
 android:background="@color/spu_light_gray" />

 <TextView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Predicted Behavior"
 android:textAppearance="@style/TextAppearance.Material3.TitleSmall"
 android:textColor="@color/spu_dark_blue" />

 <!-- Bounce -->
 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginVertical="4dp"
 android:orientation="horizontal">

 <TextView
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="Expected Bounce:"
 android:textAppearance="@style/TextAppearance.Material3.BodyMedium"
 android:textColor="@color/dark_gray" />

 <TextView
 android:id="@+id/text_bounce"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="0.0/10"
 android:textAppearance="@style/TextAppearance.Material3.BodyMedium"
 android:textColor="@color/spu_info"
 android:textStyle="bold" />
 </LinearLayout>

 <!-- Turn -->
 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginVertical="4dp"
 android:orientation="horizontal">

 <TextView
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="Expected Turn:"
 android:textAppearance="@style/TextAppearance.Material3.BodyMedium"
 android:textColor="@color/dark_gray" />

 <TextView
 android:id="@+id/text_turn"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="0.0/10"
 android:textAppearance="@style/TextAppearance.Material3.BodyMedium"
 android:textColor="@color/spu_info"
 android:textStyle="bold" />
 </LinearLayout>

 <!-- Recommendation -->
 <TextView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginTop="8dp"
 android:text="Bowling Recommendation:"
 android:textAppearance="@style/TextAppearance.Material3.BodyMedium"
 android:textColor="@color/dark_gray" />

 <TextView
 android:id="@+id/text_recommendation"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginTop="4dp"
 android:text="Analyzing pitch..."
 android:textAppearance="@style/TextAppearance.Material3.BodyLarge"
 android:textColor="@color/spu_gold"
 android:textStyle="bold" />

 </LinearLayout>
 </LinearLayout>
 </com.google.android.material.card.MaterialCardView>

 <!-- Save Analysis Button -->
 <com.google.android.material.button.MaterialButton
 android:id="@+id/btn_save_analysis"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginBottom="16dp"
 android:text="Save Analysis"
 app:backgroundTint="@color/spu_gold_dark"
 app:icon="@drawable/ic_save" />

 </LinearLayout>
 </androidx.core.widget.NestedScrollView>

 <!-- Bottom Sheet for Advanced Stats -->
 <include layout="@layout/bottom_sheet_pitch_analysis" />

</androidx.coordinatorlayout.widget.CoordinatorLayout>
```
</file_contents>


