<?xml version="1.0" encoding="utf-8"?>
<androidx.coordinatorlayout.widget.CoordinatorLayout xmlns:android="http://schemas.android.com/apk/res/android"
 xmlns:app="http://schemas.android.com/apk/res-auto"
 xmlns:tools="http://schemas.android.com/tools"
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 tools:context=".TeamManagementActivity">

 <com.google.android.material.appbar.AppBarLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:theme="@style/ThemeOverlay.AppCompat.Dark.ActionBar">

 <androidx.appcompat.widget.Toolbar
 android:id="@+id/toolbar"
 android:layout_width="match_parent"
 android:layout_height="?attr/actionBarSize"
 android:background="?attr/colorPrimary"
 app:popupTheme="@style/ThemeOverlay.AppCompat.Light" />

 <com.google.android.material.tabs.TabLayout
 android:id="@+id/tab_layout"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 app:tabMode="fixed" />

 </com.google.android.material.appbar.AppBarLayout>

 <ScrollView
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 app:layout_behavior="@string/appbar_scrolling_view_behavior">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="vertical"
 android:padding="16dp">

 <TextView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Team Names"
 android:textSize="18sp"
 android:textStyle="bold"
 android:layout_marginBottom="8dp" />

 <com.google.android.material.textfield.TextInputLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginBottom="8dp"
 style="@style/Widget.MaterialComponents.TextInputLayout.OutlinedBox">

 <EditText
 android:id="@+id/edit_home_team_name"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:hint="Home Team Name"
 android:inputType="text" />
 </com.google.android.material.textfield.TextInputLayout>

 <com.google.android.material.textfield.TextInputLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginBottom="16dp"
 style="@style/Widget.MaterialComponents.TextInputLayout.OutlinedBox">

 <EditText
 android:id="@+id/edit_away_team_name"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:hint="Away Team Name"
 android:inputType="text" />
 </com.google.android.material.textfield.TextInputLayout>

 <Button
 android:id="@+id/button_save_team_names"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Save Team Names"
 android:layout_marginBottom="24dp" />

 <TextView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Player Management"
 android:textSize="18sp"
 android:textStyle="bold"
 android:layout_marginBottom="8dp" />

 <Spinner
 android:id="@+id/spinner_team_selection"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginBottom="16dp" />

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="horizontal"
 android:gravity="center_vertical"
 android:layout_marginBottom="8dp">

 <com.google.android.material.textfield.TextInputLayout
 android:layout_width="0dp"
 android:layout_weight="1"
 android:layout_height="wrap_content"
 android:layout_marginEnd="8dp"
 style="@style/Widget.MaterialComponents.TextInputLayout.OutlinedBox">

 <EditText
 android:id="@+id/edit_player_name"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:hint="Player Name"
 android:inputType="text" />
 </com.google.android.material.textfield.TextInputLayout>

 <Spinner
 android:id="@+id/spinner_player_role"
 android:layout_width="120dp"
 android:layout_height="wrap_content" />
 </LinearLayout>

 <Button
 android:id="@+id/button_add_player"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Add Player"
 android:layout_marginBottom="16dp" />

 <TextView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Team Roster"
 android:textSize="16sp"
 android:textStyle="bold"
 android:layout_marginBottom="8dp" />

 <ListView
 android:id="@+id/list_players"
 android:layout_width="match_parent"
 android:layout_height="250dp"
 android:layout_marginBottom="16dp" />

 </LinearLayout>
 </ScrollView>

</androidx.coordinatorlayout.widget.CoordinatorLayout>
```
