```xml:app/src/main/res/layout/fragment_face_registration.xml
<?xml version="1.0" encoding="utf-8"?>
<LinearLayout xmlns:android="http://schemas.android.com/apk/res/android"
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 android:orientation="vertical">

 <TextView
 android:id="@+id/register_instructions"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:padding="16dp"
 android:text="Select a player and capture their face to register for recognition"
 android:textSize="16sp" />

 <Spinner
 android:id="@+id/player_spinner"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginHorizontal="16dp"
 android:layout_marginBottom="16dp" />

 <FrameLayout
 android:layout_width="match_parent"
 android:layout_height="0dp"
 android:layout_weight="1">

 <!-- Camera Preview Container -->
 <FrameLayout
 android:id="@+id/preview_container"
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 android:visibility="visible">

 <androidx.camera.view.PreviewView
 android:id="@+id/register_preview_view"
 android:layout_width="match_parent"
 android:layout_height="match_parent" />
 </FrameLayout>

 <!-- Captured Image Container -->
 <FrameLayout
 android:id="@+id/captured_image_container"
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 android:visibility="gone">

 <View
 android:id="@+id/preview_image_view"
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 android:layout_margin="16dp" />
 </FrameLayout>
 </FrameLayout>

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="horizontal"
 android:padding="16dp"
 android:gravity="center">

 <Button
 android:id="@+id/capture_button"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="Capture"
 android:layout_marginEnd="8dp"
 style="@style/CricketButton" />

 <Button
 android:id="@+id/save_button"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="Save"
 android:enabled="false"
 android:layout_marginStart="4dp"
 android:layout_marginEnd="4dp"
 style="@style/CricketButton" />

 <Button
 android:id="@+id/cancel_button"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="Cancel"
 android:layout_marginStart="8dp"
 style="@style/CricketButtonOutlined" />
 </LinearLayout>
</LinearLayout>
```
