<?xml version="1.0" encoding="utf-8"?>
<androidx.constraintlayout.widget.ConstraintLayout xmlns:android="http://schemas.android.com/apk/res/android"
 xmlns:app="http://schemas.android.com/apk/res-auto"
 xmlns:tools="http://schemas.android.com/tools"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:padding="8dp">

 <ImageView
 android:id="@+id/activity_icon"
 android:layout_width="40dp"
 android:layout_height="40dp"
 android:background="@drawable/circle_background"
 android:padding="8dp"
 android:src="@android:drawable/ic_menu_camera"
 app:layout_constraintStart_toStartOf="parent"
 app:layout_constraintTop_toTopOf="parent"
 app:tint="@color/primary"
 android:contentDescription="Activity type icon" />

 <TextView
 android:id="@+id/activity_title"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_marginStart="8dp"
 android:layout_marginEnd="8dp"
 android:ellipsize="end"
 android:maxLines="1"
 android:textColor="@color/black"
 android:textStyle="bold"
 app:layout_constraintEnd_toStartOf="@+id/activity_time"
 app:layout_constraintStart_toEndOf="@+id/activity_icon"
 app:layout_constraintTop_toTopOf="parent"
 tools:text="Match Completed: SPU vs Opponents" />

 <TextView
 android:id="@+id/activity_description"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_marginStart="8dp"
 android:layout_marginEnd="8dp"
 android:textColor="@color/dark_gray"
 android:textSize="14sp"
 app:layout_constraintEnd_toStartOf="@+id/activity_time"
 app:layout_constraintStart_toEndOf="@+id/activity_icon"
 app:layout_constraintTop_toBottomOf="@+id/activity_title"
 tools:text="SPU won by 45 runs" />

 <TextView
 android:id="@+id/activity_time"
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:textColor="@color/medium_gray"
 android:textSize="12sp"
 app:layout_constraintEnd_toEndOf="parent"
 app:layout_constraintTop_toTopOf="parent"
 tools:text="2h ago" />

 <View
 android:layout_width="0dp"
 android:layout_height="1dp"
 android:layout_marginTop="8dp"
 android:background="@color/light_gray"
 app:layout_constraintEnd_toEndOf="parent"
 app:layout_constraintStart_toStartOf="parent"
 app:layout_constraintTop_toBottomOf="@+id/activity_description" />

</androidx.constraintlayout.widget.ConstraintLayout>
```
