```xml:app/src/main/res/layout/activity_coach_interface.xml
<?xml version="1.0" encoding="utf-8"?>
<androidx.coordinatorlayout.widget.CoordinatorLayout xmlns:android="http://schemas.android.com/apk/res/android"
 xmlns:app="http://schemas.android.com/apk/res-auto"
 xmlns:tools="http://schemas.android.com/tools"
 android:id="@+id/coach_interface_coordinator_layout"
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 tools:context=".CoachInterfaceActivity">

 <com.google.android.material.appbar.AppBarLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:theme="@style/ThemeOverlay.Material3.Dark.ActionBar">

 <com.google.android.material.appbar.MaterialToolbar
 android:id="@+id/toolbar"
 android:layout_width="match_parent"
 android:layout_height="?attr/actionBarSize"
 android:background="?attr/colorPrimary"
 app:popupTheme="@style/ThemeOverlay.Material3.Light" />

 <com.google.android.material.tabs.TabLayout
 android:id="@+id/tab_layout"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 app:tabMode="fixed" />

 </com.google.android.material.appbar.AppBarLayout>

 <androidx.viewpager2.widget.ViewPager2
 android:id="@+id/view_pager"
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 app:layout_behavior="@string/appbar_scrolling_view_behavior">

 <!-- ViewPager2 content is controlled in the Activity -->

 </androidx.viewpager2.widget.ViewPager2>

 <!-- Team Management Layout -->
 <androidx.core.widget.NestedScrollView
 android:id="@+id/team_management_layout"
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 android:visibility="visible"
 app:layout_behavior="@string/appbar_scrolling_view_behavior">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="vertical"
 android:padding="16dp">

 <com.google.android.material.textview.MaterialTextView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Team Names"
 android:textAppearance="@style/TextAppearance.Material3.TitleLarge"
 android:layout_marginBottom="8dp" />

 <com.google.android.material.textfield.TextInputLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginBottom="8dp"
 style="@style/Widget.Material3.TextInputLayout.OutlinedBox">

 <com.google.android.material.textfield.TextInputEditText
 android:id="@+id/edit_home_team_name"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:hint="Home Team Name"
 android:inputType="text" />
 </com.google.android.material.textfield.TextInputLayout>

 <com.google.android.material.textfield.TextInputLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginBottom="16dp"
 style="@style/Widget.Material3.TextInputLayout.OutlinedBox">

 <com.google.android.material.textfield.TextInputEditText
 android:id="@+id/edit_away_team_name"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:hint="Away Team Name"
 android:inputType="text" />
 </com.google.android.material.textfield.TextInputLayout>

 <com.google.android.material.button.MaterialButton
 android:id="@+id/button_save_team_names"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Save Team Names"
 android:layout_marginBottom="24dp" />

 <com.google.android.material.textview.MaterialTextView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Player Management"
 android:textAppearance="@style/TextAppearance.Material3.TitleLarge"
 android:layout_marginBottom="8dp" />

 <com.google.android.material.textfield.MaterialAutoCompleteTextView
 android:id="@+id/spinner_team_selection"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginBottom="16dp"
 android:inputType="none"
 android:dropDownHeight="wrap_content" />

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="horizontal"
 android:gravity="center_vertical"
 android:layout_marginBottom="8dp">

 <com.google.android.material.textfield.TextInputLayout
 android:layout_width="0dp"
 android:layout_weight="1"
 android:layout_height="wrap_content"
 android:layout_marginEnd="8dp"
 style="@style/Widget.Material3.TextInputLayout.OutlinedBox">

 <com.google.android.material.textfield.TextInputEditText
 android:id="@+id/edit_player_name"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:hint="Player Name"
 android:inputType="text" />
 </com.google.android.material.textfield.TextInputLayout>

 <com.google.android.material.textfield.MaterialAutoCompleteTextView
 android:id="@+id/spinner_player_role"
 android:layout_width="120dp"
 android:layout_height="wrap_content"
 android:inputType="none"
 android:dropDownHeight="wrap_content" />
 </LinearLayout>

 <com.google.android.material.button.MaterialButton
 android:id="@+id/button_add_player"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Add Player"
 android:layout_marginBottom="16dp" />

 <com.google.android.material.textview.MaterialTextView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Team Roster"
 android:textAppearance="@style/TextAppearance.Material3.TitleMedium"
 android:layout_marginBottom="8dp" />

 <com.google.android.material.card.MaterialCardView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginBottom="16dp"
 app:cardElevation="0dp"
 app:strokeWidth="1dp"
 app:strokeColor="?attr/colorOutline">

 <ListView
 android:id="@+id/list_players"
 android:layout_width="match_parent"
 android:layout_height="250dp" />
 </com.google.android.material.card.MaterialCardView>

 </LinearLayout>
 </androidx.core.widget.NestedScrollView>

 <!-- Face Registration Layout -->
 <LinearLayout
 android:id="@+id/face_registration_layout"
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 android:orientation="vertical"
 android:visibility="gone"
 app:layout_behavior="@string/appbar_scrolling_view_behavior">

 <com.google.android.material.textview.MaterialTextView
 android:id="@+id/register_instructions"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:padding="16dp"
 android:text="Select a player and capture their face to register for recognition"
 android:textAppearance="@style/TextAppearance.Material3.BodyLarge" />

 <com.google.android.material.textfield.MaterialAutoCompleteTextView
 android:id="@+id/player_spinner"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginHorizontal="16dp"
 android:layout_marginBottom="16dp"
 android:inputType="none"
 android:dropDownHeight="wrap_content" />

 <FrameLayout
 android:layout_width="match_parent"
 android:layout_height="0dp"
 android:layout_weight="1">

 <!-- Camera Preview Container -->
 <com.google.android.material.card.MaterialCardView
 android:id="@+id/preview_container"
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 android:layout_margin="16dp"
 app:cardCornerRadius="12dp"
 app:cardElevation="2dp"
 android:visibility="visible">

 <androidx.camera.view.PreviewView
 android:id="@+id/register_preview_view"
 android:layout_width="match_parent"
 android:layout_height="match_parent" />
 </com.google.android.material.card.MaterialCardView>

 <!-- Captured Image Container -->
 <com.google.android.material.card.MaterialCardView
 android:id="@+id/captured_image_container"
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 android:layout_margin="16dp"
 app:cardCornerRadius="12dp"
 app:cardElevation="2dp"
 android:visibility="gone">

 <View
 android:id="@+id/preview_image_view"
 android:layout_width="match_parent"
 android:layout_height="match_parent" />
 </com.google.android.material.card.MaterialCardView>
 </FrameLayout>

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="horizontal"
 android:padding="16dp"
 android:gravity="center">

 <com.google.android.material.button.MaterialButton
 android:id="@+id/capture_button"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="Capture"
 android:layout_marginEnd="8dp" />

 <com.google.android.material.button.MaterialButton
 android:id="@+id/save_button"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="Save"
 android:enabled="false"
 android:layout_marginStart="4dp"
 android:layout_marginEnd="4dp" />

 <com.google.android.material.button.MaterialButton
 android:id="@+id/cancel_button"
 style="@style/Widget.Material3.Button.OutlinedButton"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="Cancel"
 android:layout_marginStart="8dp" />
 </LinearLayout>
 </LinearLayout>
</androidx.coordinatorlayout.widget.CoordinatorLayout>
```
