```xml:app/src/main/res/layout/activity_cricket_scoring.xml
<?xml version="1.0" encoding="utf-8"?>
<androidx.coordinatorlayout.widget.CoordinatorLayout xmlns:android="http://schemas.android.com/apk/res/android"
 xmlns:app="http://schemas.android.com/apk/res-auto"
 xmlns:tools="http://schemas.android.com/tools"
 android:id="@+id/coordinator_layout"
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 android:background="@color/spu_background"
 tools:context=".CricketScoringActivity">

 <com.google.android.material.appbar.AppBarLayout
 android:id="@+id/appbar_layout"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:theme="@style/ThemeOverlay.Material3.Dark.ActionBar">

 <com.google.android.material.appbar.MaterialToolbar
 android:id="@+id/toolbar"
 android:layout_width="match_parent"
 android:layout_height="?attr/actionBarSize"
 android:background="?attr/colorPrimary"
 app:popupTheme="@style/ThemeOverlay.Material3.Light"
 app:title="Cricket Scoring" />
 </com.google.android.material.appbar.AppBarLayout>

 <!-- Scoreboard Title -->
 <com.google.android.material.textview.MaterialTextView
 android:id="@+id/scoreboard_title"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:textAppearance="@style/TextAppearance.Material3.TitleMedium"
 android:gravity="center"
 android:padding="8dp"
 android:text="Team A vs Team B"
 app:layout_behavior="@string/appbar_scrolling_view_behavior"
 android:background="@color/spu_background" />

 <androidx.core.widget.NestedScrollView
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 app:layout_behavior="@string/appbar_scrolling_view_behavior">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="vertical">

 <!-- Include the cricket score panel -->
 <include
 android:id="@+id/score_panel"
 layout="@layout/cricket_score_panel"
 android:layout_width="match_parent"
 android:layout_height="wrap_content" />

 <!-- AI Player Recognition Panel -->
 <com.google.android.material.card.MaterialCardView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_margin="8dp"
 app:cardCornerRadius="16dp"
 app:cardElevation="1dp">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="vertical"
 android:padding="16dp">

 <com.google.android.material.textview.MaterialTextView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="AI Player Recognition"
 android:textAppearance="@style/TextAppearance.Material3.TitleLarge"
 android:layout_marginBottom="8dp" />

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="horizontal"
 android:gravity="center_vertical"
 android:layout_marginBottom="8dp">

 <com.google.android.material.textview.MaterialTextView
 android:id="@+id/recognition_status_text"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="Recognition Active"
 android:textAppearance="@style/TextAppearance.Material3.BodyMedium"
 android:textStyle="italic" />

 <com.google.android.material.button.MaterialButton
 android:id="@+id/toggle_camera_button"
 style="@style/Widget.Material3.Button.TextButton"
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:text="Disable Recognition" />
 </LinearLayout>

 <com.google.android.material.card.MaterialCardView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 app:cardCornerRadius="12dp">

 <FrameLayout
 android:layout_width="match_parent"
 android:layout_height="160dp">

 <androidx.camera.view.PreviewView
 android:id="@+id/camera_preview_view"
 android:layout_width="match_parent"
 android:layout_height="match_parent" />

 <View
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 android:background="@drawable/camera_border" />
 </FrameLayout>
 </com.google.android.material.card.MaterialCardView>

 <com.google.android.material.button.MaterialButton
 android:id="@+id/register_player_button"
 style="@style/Widget.Material3.Button.OutlinedButton"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Register Player Faces"
 android:layout_marginTop="8dp" />
 </LinearLayout>
 </com.google.android.material.card.MaterialCardView>

 <!-- Quick Score Controls -->
 <com.google.android.material.card.MaterialCardView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_margin="8dp"
 app:cardCornerRadius="16dp"
 app:cardElevation="1dp">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="vertical"
 android:padding="16dp">

 <com.google.android.material.textview.MaterialTextView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Quick Scoring"
 android:textAppearance="@style/TextAppearance.Material3.TitleLarge"
 android:layout_marginBottom="8dp" />

 <!-- Run buttons -->
 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="horizontal"
 android:layout_marginBottom="8dp">

 <com.google.android.material.button.MaterialButton
 android:id="@+id/button_run_0"
 style="@style/Widget.Material3.Button.OutlinedButton"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="0"
 android:textSize="18sp"
 android:layout_marginEnd="4dp" />

 <com.google.android.material.button.MaterialButton
 android:id="@+id/button_run_1"
 style="@style/Widget.Material3.Button.OutlinedButton"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="1"
 android:textSize="18sp"
 android:layout_marginEnd="4dp" />

 <com.google.android.material.button.MaterialButton
 android:id="@+id/button_run_2"
 style="@style/Widget.Material3.Button.OutlinedButton"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="2"
 android:textSize="18sp"
 android:layout_marginEnd="4dp" />

 <com.google.android.material.button.MaterialButton
 android:id="@+id/button_run_3"
 style="@style/Widget.Material3.Button.OutlinedButton"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="3"
 android:textSize="18sp"
 android:layout_marginEnd="4dp" />

 <com.google.android.material.button.MaterialButton
 android:id="@+id/button_run_4"
 style="@style/Widget.Material3.Button.TonalButton"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="4"
 android:textSize="18sp"
 app:backgroundTint="@color/spu_blue"
 android:layout_marginEnd="4dp" />

 <com.google.android.material.button.MaterialButton
 android:id="@+id/button_run_6"
 style="@style/Widget.Material3.Button.TonalButton"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="6"
 android:textSize="18sp"
 app:backgroundTint="@color/spu_accent_red" />
 </LinearLayout>

 <!-- Special buttons -->
 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="horizontal">

 <com.google.android.material.button.MaterialButton
 android:id="@+id/button_wicket"
 style="@style/Widget.Material3.Button.ElevatedButton"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="WICKET"
 app:backgroundTint="@color/spu_danger"
 android:textColor="@color/white"
 android:layout_marginEnd="4dp" />

 <com.google.android.material.button.MaterialButton
 android:id="@+id/button_extras"
 style="@style/Widget.Material3.Button.ElevatedButton"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="EXTRAS"
 app:backgroundTint="@color/spu_gold_dark"
 android:textColor="@color/black"
 android:layout_marginEnd="4dp" />

 <com.google.android.material.button.MaterialButton
 android:id="@+id/button_complete_over"
 style="@style/Widget.Material3.Button.ElevatedButton"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="OVER"
 app:backgroundTint="@color/spu_info"
 android:textColor="@color/white" />
 </LinearLayout>
 </LinearLayout>
 </com.google.android.material.card.MaterialCardView>

 <!-- Players List -->
 <androidx.recyclerview.widget.RecyclerView
 android:id="@+id/players_recycler_view"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_margin="8dp"
 android:nestedScrollingEnabled="false" />
 </LinearLayout>
 </androidx.core.widget.NestedScrollView>

 <!-- Bottom Sheet for detailed stats -->
 <androidx.core.widget.NestedScrollView
 android:id="@+id/bottom_sheet"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:background="@color/white"
 android:clipToPadding="true"
 android:elevation="16dp"
 app:behavior_hideable="false"
 app:behavior_peekHeight="0dp"
 app:layout_behavior="@string/bottom_sheet_behavior">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="vertical"
 android:padding="16dp">

 <com.google.android.material.textview.MaterialTextView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Match Statistics"
 android:textAppearance="@style/TextAppearance.Material3.HeadlineSmall"
 android:layout_marginBottom="16dp" />

 <!-- Detailed Stats Content - Will be populated dynamically -->
 <com.google.android.material.textview.MaterialTextView
 android:id="@+id/text_detailed_stats"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Detailed statistics will appear here."
 android:textAppearance="@style/TextAppearance.Material3.BodyMedium"
 android:layout_marginBottom="16dp" />
 </LinearLayout>
 </androidx.core.widget.NestedScrollView>
</androidx.coordinatorlayout.widget.CoordinatorLayout>

```
</file_contents>


