<?xml version="1.0" encoding="utf-8"?>
<androidx.coordinatorlayout.widget.CoordinatorLayout xmlns:android="http://schemas.android.com/apk/res/android"
 xmlns:app="http://schemas.android.com/apk/res-auto"
 xmlns:tools="http://schemas.android.com/tools"
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 tools:context=".ui.PlayerRegistrationActivity">

 <com.google.android.material.appbar.AppBarLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content">

 <androidx.appcompat.widget.Toolbar
 android:id="@+id/toolbar"
 android:layout_width="match_parent"
 android:layout_height="?attr/actionBarSize"
 app:title="Register Player Face"
 android:background="?attr/colorPrimary" />

 </com.google.android.material.appbar.AppBarLayout>

 <androidx.core.widget.NestedScrollView
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 app:layout_behavior="@string/appbar_scrolling_view_behavior">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 android:orientation="vertical"
 android:padding="16dp">

 <!-- Camera Section -->
 <androidx.cardview.widget.CardView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginBottom="16dp"
 app:cardCornerRadius="8dp"
 app:cardElevation="4dp">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="vertical">

 <FrameLayout
 android:layout_width="match_parent"
 android:layout_height="300dp">

 <androidx.camera.view.PreviewView
 android:id="@+id/face_camera_preview"
 android:layout_width="match_parent"
 android:layout_height="match_parent" />

 <View
 android:id="@+id/face_overlay"
 android:layout_width="160dp"
 android:layout_height="160dp"
 android:layout_gravity="center"
 android:background="@drawable/face_detection_overlay"
 android:visibility="invisible" />

 </FrameLayout>

 <TextView
 android:id="@+id/text_face_status"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:gravity="center"
 android:padding="8dp"
 android:text="Position your face in the frame"
 android:textSize="16sp" />

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:gravity="center"
 android:orientation="horizontal"
 android:padding="8dp">

 <Button
 android:id="@+id/button_capture_face"
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:text="Capture Face" />

 </LinearLayout>
 </LinearLayout>
 </androidx.cardview.widget.CardView>

 <!-- Captured Image Section -->
 <androidx.cardview.widget.CardView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginBottom="16dp"
 app:cardCornerRadius="8dp"
 app:cardElevation="4dp">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="vertical"
 android:padding="8dp">

 <TextView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:gravity="center"
 android:padding="4dp"
 android:text="Captured Face"
 android:textSize="16sp"
 android:textStyle="bold" />

 <ImageView
 android:id="@+id/image_captured_face"
 android:layout_width="160dp"
 android:layout_height="160dp"
 android:layout_gravity="center"
 android:layout_margin="8dp"
 android:scaleType="centerCrop"
 android:background="#EEEEEE"
 android:contentDescription="Captured face image" />

 <Button
 android:id="@+id/button_retake"
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:layout_gravity="center"
 android:enabled="false"
 android:text="Retake" />
 </LinearLayout>

 </androidx.cardview.widget.CardView>

 <!-- Player Information Section -->
 <androidx.cardview.widget.CardView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 app:cardCornerRadius="8dp"
 app:cardElevation="4dp">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="vertical"
 android:padding="16dp">

 <TextView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Player Information"
 android:textSize="18sp"
 android:textStyle="bold" />

 <com.google.android.material.textfield.TextInputLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginTop="8dp"
 android:hint="Player Name"
 style="@style/Widget.MaterialComponents.TextInputLayout.OutlinedBox">

 <com.google.android.material.textfield.TextInputEditText
 android:id="@+id/edit_player_name"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:inputType="textPersonName" />
 </com.google.android.material.textfield.TextInputLayout>

 <TextView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginTop="16dp"
 android:text="Player Role"
 android:textSize="16sp" />

 <RadioGroup
 android:id="@+id/radio_player_role"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginTop="8dp">

 <RadioButton
 android:id="@+id/radio_batsman"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Batsman" />

 <RadioButton
 android:id="@+id/radio_bowler"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Bowler" />

 <RadioButton
 android:id="@+id/radio_all_rounder"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="All-Rounder" />

 <RadioButton
 android:id="@+id/radio_wicket_keeper"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Wicket-Keeper" />
 </RadioGroup>

 <Button
 android:id="@+id/button_register"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginTop="16dp"
 android:enabled="false"
 android:text="Register Player" />
 </LinearLayout>
 </androidx.cardview.widget.CardView>
 </LinearLayout>
 </androidx.core.widget.NestedScrollView>

</androidx.coordinatorlayout.widget.CoordinatorLayout>

```
