 android:layout_width="match_parent"
 android:layout_height="match_parent"
 android:background="@color/spu_background"
 tools:context=".RegisterPlayerFaceActivity">

 <!-- Top App Bar -->
 <com.google.android.material.appbar.AppBarLayout
 android:id="@+id/appbar_layout"
 android:layout_width="match_parent"
 android:layout_height="wrap_content">

 <androidx.appcompat.widget.Toolbar
 android:id="@+id/toolbar"
 android:layout_width="match_parent"
 android:layout_height="?attr/actionBarSize"
 android:background="@color/spu_dark_blue"
 app:titleTextColor="@color/white"
 app:title="Register Player Face" />
 </com.google.android.material.appbar.AppBarLayout>

 <!-- Main Content -->
 <androidx.core.widget.NestedScrollView
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 app:layout_behavior="@string/appbar_scrolling_view_behavior">

 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="vertical"
 android:padding="16dp">

 <TextView
 android:id="@+id/register_instructions"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Register a player's face for automatic recognition"
 android:textSize="16sp"
 android:textStyle="bold"
 android:layout_marginBottom="16dp" />

 <!-- Player Selection -->
 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="vertical"
 android:layout_marginBottom="16dp">

 <TextView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Select Player"
 android:textSize="14sp"
 android:layout_marginBottom="4dp" />

 <Spinner
 android:id="@+id/player_spinner"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginBottom="8dp" />

 <TextView
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:text="Player Role"
 android:textSize="14sp"
 android:layout_marginBottom="4dp" />

 <Spinner
 android:id="@+id/role_spinner"
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:layout_marginBottom="8dp" />
 </LinearLayout>

 <!-- Camera Preview -->
 <FrameLayout
 android:id="@+id/preview_container"
 android:layout_width="match_parent"
 android:layout_height="300dp"
 android:layout_marginBottom="16dp">

 <androidx.camera.view.PreviewView
 android:id="@+id/register_preview_view"
 android:layout_width="match_parent"
 android:layout_height="match_parent" />

 <View
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 android:background="@drawable/camera_border" />
 </FrameLayout>

 <!-- Captured Image Preview -->
 <FrameLayout
 android:id="@+id/captured_image_container"
 android:layout_width="match_parent"
 android:layout_height="300dp"
 android:layout_marginBottom="16dp"
 android:visibility="gone">

 <View
 android:id="@+id/preview_image_view"
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 android:background="@drawable/camera_border" />
 </FrameLayout>

 <!-- Button Controls -->
 <LinearLayout
 android:layout_width="match_parent"
 android:layout_height="wrap_content"
 android:orientation="horizontal">

 <Button
 android:id="@+id/capture_button"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="Capture"
 android:layout_marginEnd="8dp" />

 <Button
 android:id="@+id/save_button"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="Save"
 android:enabled="false"
 android:layout_marginEnd="8dp" />

 <Button
 android:id="@+id/cancel_button"
 android:layout_width="0dp"
 android:layout_height="wrap_content"
 android:layout_weight="1"
 android:text="Cancel"
 style="@style/Widget.MaterialComponents.Button.TextButton" />
 </LinearLayout>
 </LinearLayout>
 </androidx.core.widget.NestedScrollView>
</androidx.coordinatorlayout.widget.CoordinatorLayout>
