package com.finedine.spucricketclub.models;

/**
 * Model class to hold win probability data for teams
 */
public class WinProbability {
 private String teamName;
 private float probability;

 public WinProbability() {
 }

 public WinProbability(String teamName, float probability) {
 this.teamName = teamName;
 this.probability = probability;
 }

 /**
 * @return The name of the team
 */
 public String getTeamName() {
 return teamName;
 }

 /**
 * @param teamName The team name to set
 */
 public void setTeamName(String teamName) {
 this.teamName = teamName;
 }

 /**
 * @return The win probability for the team (0-100)
 */
 public float getProbability() {
 return probability;
 }

 /**
 * @param probability The probability to set
 */
 public void setProbability(float probability) {
 this.probability = probability;
 }

 /**
 * @return Team probability as a percentage string
 */
 public String getProbabilityPercent() {
 return String.format("%.1f%%", probability);
 }
}
