 -->\n <TextView\n android:layout_width=\"match_parent\"\n android:layout_height=\"wrap_content\"\n android:layout_marginBottom=\"8dp\"\n android:text=\"Analysis Timeline\"\n android:textAppearance=\"@style/TextAppearance.Material3.TitleMedium\"\n android:textColor=\"@color/spu_dark_blue\" />\n\n <com.google.android.material.card.MaterialCardView\n android:layout_width=\"match_parent\"\n android:layout_height=\"200dp\"\n android:layout_marginBottom=\"16dp\"\n app:cardCornerRadius=\"12dp\"\n app:cardElevation=\"2dp\">\n\n <!-- Timeline chart would go here in a real implementation -->\n <TextView\n android:layout_width=\"match_parent\"\n android:layout_height=\"match_parent\"\n android:gravity=\"center\"\n android:text=\"Pitch condition changes over time\"\n android:textAppearance=\"@style/TextAppearance.Material3.BodyLarge\" />\n </com.google.android.material.card.MaterialCardView>\n\n <!-- Pitch Wear Map -->\n <TextView\n android:layout_width=\"match_parent\"\n android:layout_height=\"wrap_content\"\n android:layout_marginBottom=\"8dp\"\n android:layout_marginTop=\"8dp\"\n android:text=\"Pitch Wear Map\"\n android:textAppearance=\"@style/TextAppearance.Material3.TitleMedium\"\n android:textColor=\"@color/spu_dark_blue\" />\n\n <com.google.android.material.card.MaterialCardView\n android:layout_width=\"match_parent\"\n android:layout_height=\"240dp\"\n android:layout_marginBottom=\"16dp\"\n app:cardCornerRadius=\"12dp\"\n app:cardElevation=\"2dp\">\n\n <!-- Wear map would go here in a real implementation -->\n <FrameLayout\n android:layout_width=\"match_parent\"\n android:layout_height=\"match_parent\"\n android:padding=\"8dp\">\n\n <ImageView\n android:layout_width=\"match_parent\"\n android:layout_height=\"match_parent\"\n android:contentDescription=\"Pitch wear map\"\n android:scaleType=\"fitCenter\"\n android:src=\"@drawable/ic_menu_camera\" />\n\n <TextView\n android:layout_width=\"wrap_content\"\n android:layout_height=\"wrap_content\"\n android:layout_gravity=\"bottom|center_horizontal\"\n android:background=\"#80000000\"\n android:padding=\"8dp\"\n android:text=\"Pitch wear patterns\"\n android:textColor=\"@color/white\" />\n </FrameLayout>\n </com.google.android.material.card.MaterialCardView>\n\n <!-- Additional Analysis Data -->\n <TextView\n android:layout_width=\"match_parent\"\n android:layout_height=\"wrap_content\"\n android:layout_marginBottom=\"8dp\"\n android:layout_marginTop=\"8dp\"\n android:text=\"Strategic Recommendations\"\n android:textAppearance=\"@style/TextAppearance.Material3.TitleMedium\"\n android:textColor=\"@color/spu_dark_blue\" />\n\n <com.google.android.material.card.MaterialCardView\n android:layout_width=\"match_parent\"\n android:layout_height=\"wrap_content\"\n android:layout_marginBottom=\"16dp\"\n app:cardCornerRadius=\"12dp\"\n app:cardElevation=\"2dp\">\n\n <LinearLayout\n android:layout_width=\"match_parent\"\n android:layout_height=\"wrap_content\"\n android:orientation=\"vertical\"\n android:padding=\"16dp\">\n\n <!-- Fast Bowlers -->\n <TextView\n android:layout_width=\"match_parent\"\n android:layout_height=\"wrap_content\"\n android:layout_marginBottom=\"8dp\"\n android:text=\"For Fast Bowlers\"\n android:textAppearance=\"@style/TextAppearance.Material3.TitleSmall\"\n android:textColor=\"@color/spu_dark_blue\" />\n\n <TextView\n android:id=\"@+id/text_fast_bowler_recommendation\"\n android:layout_width=\"match_parent\"\n android:layout_height=\"wrap_content\"\n android:layout_marginBottom=\"16dp\"\n android:text=\"Target full length and aim for seam movement. Slower balls could be effective as the pitch appears to hold.\"\n android:textAppearance=\"@style/TextAppearance.Material3.BodyMedium\" />\n\n <!-- Spin Bowlers -->\n <TextView\n android:layout_width=\"match_parent\"\n android:layout_height=\"wrap_content\"\n android:layout_marginBottom=\"8dp\"\n android:text=\"For Spin Bowlers\"\n android:textAppearance=\"@style/TextAppearance.Material3.TitleSmall\"\n android:textColor=\"@color/spu_dark_blue\" />\n\n <TextView\n android:id=\"@+id/text_spin_bowler_recommendation\"\n android:layout_width=\"match_parent\"\n android:layout_height=\"wrap_content\"\n android:layout_marginBottom=\"16dp\"\n android:text=\"Flight the ball and target rough patches in middle-to-leg stump line. The pitch shows potential for turn and bounce.\"\n android:textAppearance=\"@style/TextAppearance.Material3.BodyMedium\" />\n\n <!-- Batsmen -->\n <TextView\n android:layout_width=\"match_parent\"\n android:layout_height=\"wrap_content\"\n android:layout_marginBottom=\"8dp\"\n android:text=\"For Batsmen\"\n android:textAppearance=\"@style/TextAppearance.Material3.TitleSmall\"\n android:textColor=\"@color/spu_dark_blue\" />\n\n <TextView\n android:id=\"@+id/text_batsman_recommendation\"\n android:layout_width=\"match_parent\"\n android:layout_height=\"wrap_content\"\n android:text=\"Watch for variable bounce. Play with soft hands when ball is pitched on good length. Front foot defense is safer than back foot.\"\n android:textAppearance=\"@style/TextAppearance.Material3.BodyMedium\" />\n </LinearLayout>\n </com.google.android.material.card.MaterialCardView>\n </LinearLayout>\n</androidx.core.widget.NestedScrollView>"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"toolu_bdrk_01EpXnYFma3RppwMPAApchuF","content":"The apply model made the following changes to the file:

