+
+ /**
+ * Generate a ball and update match data
+ */
+ private void generateBall() {
+ if (!isGenerating) {
+ return;
+ }
+
+ // Simulate this ball
+ ballsGenerated++;
+ ballInOver++;
+
+ boolean isWicket = false;
+ int runs = 0;
