_height=\"0dp\"\n app:layout_constraintTop_toTopOf=\"parent\"\n app:layout_constraintStart_toStartOf=\"parent\"\n app:layout_constraintEnd_toEndOf=\"parent\"\n app:layout_constraintBottom_toTopOf=\"@+id/bottom_controls_guideline\" />\n\n <!-- Guideline for bottom controls -->\n <androidx.constraintlayout.widget.Guideline\n android:id=\"@+id/bottom_controls_guideline\"\n android:layout_width=\"wrap_content\"\n android:layout_height=\"wrap_content\"\n android:orientation=\"horizontal\"\n app:layout_constraintGuide_percent=\"0.75\" />\n\n <!-- AI Tracking Status Overlay -->\n <com.google.android.material.card.MaterialCardView\n android:id=\"@+id/ai_status_overlay\"\n android:layout_width=\"wrap_content\"\n android:layout_height=\"wrap_content\"\n android:layout_margin=\"16dp\"\n app:cardBackgroundColor=\"#A0000000\"\n app:cardCornerRadius=\"8dp\"\n app:contentPadding=\"8dp\"\n app:layout_constraintTop_toTopOf=\"@+id/camera_preview\"\n app:layout_constraintEnd_toEndOf=\"@+id/camera_preview\">\n\n <LinearLayout\n android:layout_width=\"wrap_content\"\n android:layout_height=\"wrap_content\"\n android:orientation=\"vertical\"\n android:gravity=\"center_horizontal\">\n\n <TextView\n android:id=\"@+id/text_ai_status_title\"\n android:layout_width=\"wrap_content\"\n android:layout_height=\"wrap_content\"\n android:text=\"AI Tracking\"\n android:textColor=\"@color/spu_gold\"\n android:textSize=\"14sp\"\n android:textStyle=\"bold\" />\n\n <TextView\n android:id=\"@+id/text_ai_status_message\"\n android:layout_width=\"wrap_content\"\n android:layout_height=\"wrap_content\"\n android:text=\"Initializing...\"\n android:textColor=\"@color/white\"\n android:textSize=\"12sp\" />\n </LinearLayout>\n </com.google.android.material.card.MaterialCardView>\n\n\n <!-- Cricket Score Panel -->\n <include\n android:id=\"@+id/cricket_score_panel_main\"\n layout=\"@layout/cricket_score_panel\"\n android:layout_width=\"0dp\"\n android:layout_height=\"wrap_content\"\n app:layout_constraintBottom_toBottomOf=\"@+id/camera_preview\"\n app:layout_constraintStart_toStartOf=\"parent\"\n app:layout_constraintEnd_toEndOf=\"parent\" />\n\n <!-- Bottom Control Sheet -->\n <com.google.android.material.card.MaterialCardView\n android:id=\"@+id/bottom_control_sheet\"\n android:layout_width=\"0dp\"\n android:layout_height=\"0dp\"\n app:cardBackgroundColor=\"@color/spu_dark_blue_transparent\"\n app:cardCornerRadius=\"16dp\"\n app:cardElevation=\"8dp\"\n app:layout_constraintTop_toBottomOf=\"@id/bottom_controls_guideline\"\n app:layout_constraintStart_toStartOf=\"parent\"\n app:layout_constraintEnd_toEndOf=\"parent\"\n app:layout_constraintBottom_toBottomOf=\"parent\">\n\n <LinearLayout\n android:layout_width=\"match_parent\"\n android:layout_height=\"match_parent\"\n android:orientation=\"vertical\"\n android:padding=\"16dp\">\n\n <TextView\n android:layout_width=\"wrap_content\"\n android:layout_height=\"wrap_content\"\n android:text=\"AI Tracking Controls\"\n android:textColor=\"@color/spu_gold\"\n android:textSize=\"16sp\"\n android:textStyle=\"bold\"\n android:layout_marginBottom=\"8dp\"/>\n\n <LinearLayout\n android:layout_width=\"match_parent\"\n android:layout_height=\"wrap_content\"\n android:orientation=\"horizontal\"\n android:layout_marginBottom=\"8dp\">\n\n <com.google.android.material.button.MaterialButtonToggleGroup\n android:id=\"@+id/toggle_ai_tracking_group\"\n android:layout_width=\"match_parent\"\n android:layout_height=\"wrap_content\"\n app:singleSelection=\"false\"\n app:selectionRequired=\"false\">\n\n <Button\n android:id=\"@+id/btn_toggle_ball_tracking\"\n style=\"?attr/materialButtonOutlinedStyle\"\n android:layout_width=\"0dp\"\n android:layout_height=\"wrap_content\"\n android:layout_weight=\"1\"\n android:text=\"Ball\"\n app:icon=\"@drawable/ic_ball_tracking\" />\n\n <Button\n android:id=\"@+id/btn_toggle_player_tracking\"\n style=\"?attr/materialButtonOutlinedStyle\"\n android:layout_width=\"0dp\"\n android:layout_height=\"wrap_content\"\n an