 private void setupFirebase() {
 // Enable offline persistence
 FirebaseDatabase.getInstance().setPersistenceEnabled(true);

 // Set disk cache size to 20MB for Firebase
 FirebaseDatabase.getInstance().getReference().keepSynced(true);

 Log.d(TAG, "Firebase initialized with offline persistence");
 }

 private void resetMatchData() {
 editTextPlayerName.setText("");
 playerScoresDisplay.setLength(0);
 playerNames.clear();
 playerScores.clear();
 updatePlayerScoresDisplay();

 if (cricketMatchService != null) {
 cricketMatchService.resetMatch();
 currentMatch = null;
 }

 resetCricketScorePanel();

 Toast.makeText(this, "Match data reset", Toast.LENGTH_SHORT).show();
 }

 private void initializeCricketScorePanel() {
 TextView textTeamBatting = findViewById(R.id.text_team_batting);
 TextView textTeamBowling = findViewById(R.id.text_team_bowling);
 TextView textScore = findViewById(R.id.text_score);
 TextView textOvers = findViewById(R.id.text_overs);
 TextView textTarget = findViewById(R.id.text_target);

 cricketMatchService = CricketMatchService.getInstance(this);
 if (currentMatch == null && cricketMatchService != null) {
 currentMatch = cricketMatchService.createMatch("SPU", "Opponent", 20);
 }

 if (currentMatch != null) {
 teamBatting = currentMatch.getTeamBatting().getTeamName();
 teamBowling = currentMatch.getTeamBowling().getTeamName();
 targetScore = currentMatch.getTargetScore();
 updateCricketUIFromModel();
 } else {
 if (textTeamBatting != null) textTeamBatting.setText(teamBatting);
 if (textTeamBowling != null) textTeamBowling.setText(teamBowling);
 if (textScore != null) textScore.setText(String.format("%d/%d", 0, 0));
 if (textOvers != null) textOvers.setText(String.format("(%d.%d ov)", 0, 0));
 if (textTarget != null)
 textTarget.setText(String.format(getString(R.string.target_label), targetScore));
