 wickets, runs, overs, balls));
 }
 }

 private void setupCurrentOverDisplay() { // Adapt for simplified panel
 TextView textThisOver = findViewById(R.id.text_this_over_simplified);
 if (textThisOver != null) {
 // Build "This Over: " string based on currentOverBalls array or from Match model
 StringBuilder overSummary = new StringBuilder("This Over: ");
 boolean firstBall = true;
 for (int ballOutcome : currentOverBalls) { // Assuming currentOverBalls stores actual runs or W for wicket
 if (ballOutcome == -1) break; // -1 could signify end of recorded balls in over
 if (!firstBall) overSummary.append(" ");

 if (ballOutcome == 0 && ballsInCurrentOver > 0) overSummary.append("•"); // Dot ball
 else if (ballOutcome > 0) overSummary.append(ballOutcome);
 else if (ballOutcome == -2) overSummary.append("W"); // Assuming -2 for Wicket
 // Add Wd, Nb etc. if tracked
 firstBall = false;
 }
 textThisOver.setText(overSummary.toString());
 }
 }

 // private void updateCurrentOverDisplay() { // This logic is now part of setupCurrentOverDisplay or needs live updates
 // }

 private void updateCricketUIFromModel() {
 if (currentMatch == null) {
 Log.d(TAG, "updateCricketUIFromModel: currentMatch is null");
 initializeCricketScorePanel(); // Attempt to re-initialize with default or new match
 return;
 }

 Innings innings = currentMatch.getCurrentInnings();
 if (innings == null) {
 Log.e(TAG, "updateCricketUIFromModel: currentInnings is null for match " + currentMatch.getMatchName());
 return;
 }


 currentScore = innings.getTotalScore();
 wickets = innings.getWickets();

 float totalOversFloat = innings.getTotalOvers();
 oversCompleted = (int) totalOversFloat;
 ballsInCurrentOver = (int) Math.round((totalOversFloat - oversCompleted) * 10);
 if (ballsInCurrentOver >=6) { // Handle precision issues
 oversCompleted += ballsInCurrentOver / 6;
 ballsInCurrentOver = ballsInCurrentOver % 6;
 }


 Player striker = innings.getStriker();
 Player nonStriker = innings.getNonStriker();

 batsman1Name = (striker != null) ? striker.getName() : "Striker";
 batsman1Score = (striker != null && striker.getBattingStats() != null) ? striker.getBattingStats().getRuns() : 0;
 batsman1Balls = (striker != null && striker.getBattingStats() != null) ? striker.getBattingStats().getBallsFaced() : 0;

 batsman2Name = (nonStriker != null) ? nonStriker.getName() : "Non-Striker";
 batsman2Score = (nonStriker != null && nonStriker.getBattingStats() != null) ? nonStriker.getBattingStats().getRuns() : 0;
 batsman2Balls = (nonStriker != null && nonStriker.getBattingStats() != null) ? nonStriker.getBattingStats().getBallsFaced() : 0;

 setupBatsmenInfo(batsman1Name, batsman2Name, batsman1Score, batsman2Score, batsman1Balls, batsman2Balls);

 Player bowler = innings.getCurrentBowler();
 if (bowler != null && bowler.getBowlingStats() != null) {
 currentBowlerName = bowler.getName();
 bowlerWickets = bowler.getBowlingStats().getWickets();
 bowlerRuns = bowler.getBowlingStats().getRunsConceded();
 // Assuming BowlingStats.getOvers() returns full overs and getBallsInCurrentOver() for partial
 bowlerOvers = bowler.getBowlingStats().getOvers(); 
 bowlerBalls = bowler.getBowlingStats().getBallsInCurrentOver();
 setupBowlerInfo(currentBowlerName, bowlerWickets, bowlerRuns, bowlerOvers, bowlerBalls);
 } else {
 setupBowlerInfo("Bowler",0,0,0,0);
 }

 // Update general score UI
 TextView textTeamBatting = findViewById(R.id.text_team_batting_name_simplified);
 TextView textScore = findViewById(R.id.text_team_score_simplified);
 TextView textOvers = findViewById(R.id.text_overs_simplified);
 TextView textTarget = findViewById(R.id.text_target_simplified);

 if (textTeamBatting != null) textTeamBatting.setText(currentMatch.getTeamBatting() != null ? currentMatch.getTeamBatting().getTeamName() : "Team A");
 if (textScore != null) textScore.setText(String.format(Locale.getDefault(), "%d-%d", currentScore, wickets));
 if (textOvers != null) textOvers.setText(String.format(Locale.getDefault(), "(%d.%d)", oversCompleted, ballsInCurrentOver));

 if (textTarget != null) {
 int target = currentMatch.getTargetScore();
 if (target > 0 && currentMatch.getInnings().size() > 1) { // Show target only in 2nd innings
 textTarget.setText(String.format(Locale.getDefault(),"TGT %d", target));
 textTarget.setVisibility(View.VISIBLE);
 } else {
 textTarget.setVisibility(View.GONE);
 }
 }

 // Update "This Over" display (more complex, might need Ball objects list from Over)
 Over currentOverObj = innings.getCurrentOver();
 TextView textThisOver = findViewById(R.id.text_this_over_simplified);
 if (textThisOver != null && currentOverObj != null) {
 StringBuilder overSummary = new StringBuilder("This Over: ");
 List<Ball> ballsInOver = currentOverObj.getBalls();
 for (int i = 0; i < ballsInOver.size(); i++) {
 Ball ball = ballsInOver.get(i);
 if (ball.isWicket()) overSummary.append("W ");
 else if (ball.getRunsScored() == 0 && !ball.isExtra()) overSummary.append("• ");
 else if (ball.isExtra()) {
 if (ball.getBallType() == Ball.BallType.WIDE) overSummary.append("Wd ");
 else if (ball.getBallType() == Ball.BallType.NO_BALL) overSummary.append(ball.getRunsScored() > 0 ? (ball.getRunsScored()-1) + "Nb " : "Nb "); // runs scored + NoBall
 // TODO: Add Byes, LegByes if tracked
 }
 else overSummary.append(ball.getRunsScored()).append(" ");
 }
 textThisOver.setText(overSummary.toString().trim());
 } else if (textThisOver != null) {
 textThisOver.setText("This Over: ");
 }
 }


