 private void updateThisOverDisplay(Innings innings) {
 TextView textThisOver = findViewById(R.id.text_this_over_simplified);
 if (textThisOver != null && innings != null && innings.getCurrentOver() != null) {
 Over currentOverObj = innings.getCurrentOver();
 StringBuilder overSummary = new StringBuilder("This Over: ");
 List<Ball> ballsInOver = currentOverObj.getBalls();
 for (int i = 0; i < ballsInOver.size(); i++) {
 Ball ball = ballsInOver.get(i);
 if (ball.isWicket()) overSummary.append("W ");
 else if (ball.isExtra()) {
 if (ball.getBallType() == Ball.BallType.WIDE) overSummary.append("Wd ");
 else if (ball.getBallType() == Ball.BallType.NO_BALL) {
 overSummary.append(ball.getRunsScored() > 0 ? (ball.getRunsScored() -1) + "Nb " : "Nb ");
 } else if (ball.getBallType() == Ball.BallType.BYE) {
 overSummary.append(ball.getRunsScored()).append("B ");
 } else if (ball.getBallType() == Ball.BallType.LEG_BYE) {
 overSummary.append(ball.getRunsScored()).append("Lb ");
 }
 } else if (ball.getRunsScored() == 0) overSummary.append("• ");
 else overSummary.append(ball.getRunsScored()).append(" ");
 }
 textThisOver.setText(overSummary.toString().trim());
 } else if (textThisOver != null) {
 textThisOver.setText("This Over: ");
 }
 }


 private void updateCricketUIFromModel() {
 if (currentMatch == null) {
 Log.d(TAG, "updateCricketUIFromModel: currentMatch is null. Initializing panel.");
 initializeCricketScorePanel(); // This will create/get a match
 if (currentMatch == null) { // Still null after init, something is wrong
 Log.e(TAG, "Failed to initialize or get currentMatch in updateCricketUIFromModel.");
 return; // Prevent further execution if match is still null
 }
 }

 Innings innings = currentMatch.getCurrentInnings();
 if (innings == null) {
 Log.e(TAG, "updateCricketUIFromModel: currentInnings is null for match " + currentMatch.getMatchName());
 // Potentially create a new innings if appropriate for the app's logic flow
 // For now, we'll just display default empty values if innings is null
 teamBatting = currentMatch.getTeamBatting() != null ? currentMatch.getTeamBatting().getTeamName() : "Team A";
 currentScore = 0;
 wickets = 0;
 oversCompleted = 0;
 ballsInCurrentOver = 0;
 batsman1Name = "Striker";
 batsman1Score = 0;
 batsman1Balls = 0;
 batsman2Name = "Non-Striker";
 batsman2Score = 0;
 batsman2Balls = 0;
 currentBowlerName = "Bowler";
 bowlerWickets = 0;
 bowlerRuns = 0;
 bowlerOvers = 0;
 bowlerBallsInOver = 0;
 } else {
 teamBatting = currentMatch.getTeamBatting() != null ? currentMatch.getTeamBatting().getTeamName() : "Team A"; // Fallback
 currentScore = innings.getTotalScore();
 wickets = innings.getWickets();
 float totalOversFloat = innings.getTotalOvers();
 oversCompleted = (int) totalOversFloat;
 ballsInCurrentOver = (int) Math.round((totalOversFloat - oversCompleted) * 100) / 10; // More precise for .1, .2 etc.
 if (ballsInCurrentOver >=6) {
 oversCompleted += ballsInCurrentOver / 6;
 ballsInCurrentOver = ballsInCurrentOver % 6;
 }

 Player striker = innings.getStriker();
 Player nonStriker = innings.getNonStriker();
 batsman1Name = (striker != null) ? striker.getName() : "Striker";
 batsman1Score = (striker != null && striker.getBattingStats() != null) ? striker.getBattingStats().getRuns() : 0;
 batsman1Balls = (striker != null && striker.getBattingStats() != null) ? striker.getBattingStats().getBallsFaced() : 0;
 batsman2Name = (nonStriker != null) ? nonStriker.getName() : "Non-Striker";
 batsman2Score = (nonStriker != null && nonStriker.getBattingStats() != null) ? nonStriker.getBattingStats().getRuns() : 0;
 batsman2Balls = (nonStriker != null && nonStriker.getBattingStats() != null) ? nonStriker.getBattingStats().getBallsFaced() : 0;

 Player bowler = innings.getCurrentBowler();
 if (bowler != null && bowler.getBowlingStats() != null) {
 currentBowlerName = bowler.getName();
 bowlerWickets = bowler.getBowlingStats().getWickets();
 bowlerRuns = bowler.getBowlingStats().getRunsConceded();
 bowlerOvers = bowler.getBowlingStats().getOvers();
 bowlerBallsInOver = bowler.getBowlingStats().getBallsInCurrentOver();
 } else {
 currentBowlerName = "Bowler";
 bowlerWickets = 0;
 bowlerRuns = 0;
 bowlerOvers = 0;
 bowlerBallsInOver = 0;
 }
 }

 setupBatsmenInfo(batsman1Name, batsman2Name, batsman1Score, batsman2Score, batsman1Balls, batsman2Balls);
 setupBowlerInfo(currentBowlerName, bowlerWickets, bowlerRuns, bowlerOvers, bowlerBallsInOver);

 TextView textTeamBattingView = findViewById(R.id.text_team_batting_name_simplified);
 TextView textScoreView = findViewById(R.id.text_team_score_simplified);
 TextView textOversView = findViewById(R.id.text_overs_simplified);
 TextView textTargetView = findViewById(R.id.text_target_simplified);

 if (textTeamBattingView != null) textTeamBattingView.setText(teamBatting.toUpperCase());
 if (textScoreView != null) textScoreView.setText(String.format(Locale.getDefault(), "%d-%d", currentScore, wickets));
 if (textOversView != null) textOversView.setText(String.format(Locale.getDefault(), "(%d.%d)", oversCompleted, ballsInCurrentOver));

 if (textTargetView != null) {
 int target = currentMatch.getTargetScore(); // Use local targetScore if currentMatch could be null earlier
 if (target > 0 && currentMatch.getInnings().size() > 1) {
 textTargetView.setText(String.format(Locale.getDefault(),"TGT %d", target));
 textTargetView.setVisibility(View.VISIBLE);
 } else {
 textTargetView.setVisibility(View.GONE);
 }
 }
 if (innings != null) {
 updateThisOverDisplay(innings);
 } else {
 TextView textThisOver = findViewById(R.id.text_this_over_simplified);
 if(textThisOver != null) textThisOver.setText("This Over: ");
 }
 }


