 super.onResume();
 if (!isInitialized && allPermissionsGranted()) {
 initializeCameraAndHelpers(); // Initialize camera if permissions are now granted
 isInitialized = true;
 }
 // Always refresh UI from model on resume, as match state might have changed
 if (cricketMatchService != null) { // Ensure service is available
 currentMatch = cricketMatchService.getCurrentMatch(); // Get potentially updated match
 updateCricketUIFromModel();
 } else {
 Log.e(TAG, "CricketMatchService is null in onResume");
