port com.finedine.spucricketclub.cricket.Team; // Not directly used in this class after refactor\n\nimport androidx.activity.EdgeToEdge;\nimport androidx.annotation.NonNull;\nimport androidx.appcompat.app.AlertDialog;\nimport androidx.appcompat.app.AppCompatActivity;\nimport androidx.appcompat.widget.Toolbar;\nimport androidx.camera.core.Camera;\nimport androidx.camera.core.CameraSelector;\nimport androidx.camera.core.ImageAnalysis;\nimport androidx.camera.core.ImageProxy;\nimport androidx.camera.core.Preview;\nimport androidx.camera.video.FileOutputOptions;\nimport androidx.camera.video.Quality;\nimport androidx.camera.video.QualitySelector;\nimport androidx.camera.video.Recorder;\nimport androidx.camera.video.Recording;\nimport androidx.camera.video.VideoCapture;\nimport androidx.camera.video.VideoRecordEvent;\nimport androidx.camera.lifecycle.ProcessCameraProvider;\nimport androidx.core.app.ActivityCompat;\nimport androidx.core.content.ContextCompat;\nimport androidx.core.graphics.Insets;\nimport androidx.core.view.ViewCompat;\nimport androidx.core.view.WindowInsetsCompat;\n// import androidx.fragment.app.Fragment; // Not used\n// import androidx.recyclerview.widget.LinearLayoutManager; // Obsolete\n// import androidx.recyclerview.widget.RecyclerView; // Obsolete\n\n// import com.google.android.material.bottomsheet.BottomSheetDialog; // Obsolete\nimport com.google.android.material.floatingactionbutton.FloatingActionButton;\n// import com.google.android.material.tabs.TabLayout; // Not in new layout\nimport com.google.common.util.concurrent.ListenableFuture;\n\nimport java.text.SimpleDateFormat;\nimport java.util.ArrayList;\n// import java.util.HashMap; // Obsolete playerScores\nimport java.util.List;\nimport java.util.Locale;\n// import java.util.Map; // Obsolete playerScores\nimport java.util.concurrent.ExecutionException;\n\nimport androidx.camera.core.ExperimentalGetImage;\n\n\n@ExperimentalGetImage\npublic class MainActivity extends AppCompatActivity {\n\n private static final String TAG = \"MainActivity\";\n private static final int REQUEST_CODE_PERMISSIONS = 10;\n private final String[] REQUIRED_PERMISSIONS;\n\n {\n if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {\n REQUIRED_PERMISSIONS = new String[]{\n Manifest.permission.CAMERA,\n Manifest.permission.RECORD_AUDIO,\n Manifest.permission.READ_MEDIA_IMAGES,\n Manifest.permission.READ_MEDIA_VIDEO\n };\n } else if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {\n REQUIRED_PERMISSIONS = new String[]{\n Manifest.permission.CAMERA,\n Manifest.permission.RECORD_AUDIO\n };\n } else {\n REQUIRED_PERMISSIONS = new String[]{\n Manifest.permission.CAMERA,\n Manifest.permission.RECORD_AUDIO,\n Manifest.permission.WRITE_EXTERNAL_STORAGE\n };\n }\n }\n\n private androidx.camera.view.PreviewView cameraPreviewBroadcast;\n private Toolbar toolbar;\n private TextView textAiStatusMessage;\n private MaterialButtonToggleGroup toggleAiTrackingGroup;\n private Button btnToggleBallTracking;\n private Button btnTogglePlayerTracking;\n private Button btnTogglePoseEstimation;\n private Button buttonStartRecordingMain;\n private Button buttonQuickWicketMain;\n private FloatingActionButton fabMainAction;\n\n private ProcessCameraProvider cameraProvider;\n private Camera camera;\n private Preview preview;\n private VideoCapture<Recorder> videoCapture;\n private Recording recording;\n private ImageAnalysis imageAnalysis;\n\n private FaceRecognitionHelper faceRecognitionHelper;\n private ShirtNumberRecognitionHelper shirtNumberRecognitionHelper;\n\n private boolean isAiBallTrackingEnabled = false;\n private boolean isAiPlayerTrackingEnabled = false;\n private boolean isAiPoseEstimationEnabled = false;\n private boolean isRecording = false;\n private boolean isInitialized = false;\n\n private CricketMatchService cricketMatchService;\n private Match currentMatch;\n\n // Local game state holders for UI display (synced from currentMatch)\n private String teamBattingName = \"Team A\";\n private int currentDisplayedScore = 0;\n private int currentDisplayedWickets = 0;\n private int currentDisplayedOversCompleted = 0;\n private int currentDisplayedBallsInOver = 0;\n private String batsman1DisplayNome = \"Batsman 1\";\n private int batsman1DisplayScore = 0;\n private int batsman1DisplayBalls = 0;\n private String batsman2DisplayNome = \"Batsman 2\";\n private int batsman2DisplayScore = 0;\n private int batsman2DisplayBalls = 0;\n private String bowlerDisplayName = \"Bowler\";\n private int bowlerDisplayWickets = 0;\n private int bowlerDisplayRuns = 0;\n private int bowlerDisplayOvers = 0;\n private int bowlerDisplayBallsInOver = 0;\n // private final ArrayList<String> currentOverBallStrings = new ArrayList<>(); // Replaced by logic in updateThisOverDisplay\n\n\n @Override\n protected void onCreate(Bundle savedInstanceState) {\n super.onCreate(savedInstanceState);\n EdgeToEdge.enable(this);\n setContentView(R.layout.activity_main);\n\n setupFirebase();\n cricketMatchService = CricketMatchService.getInstance(this);\n initializeUIComponents();\n setupButtonListeners();\n updateAiStatusDisplay();\n\n ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main_broadcast_layout), (v, insets) -> {\n Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());\n v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);\n return insets;\n });\n\n checkPermissionsAndInitialize();\n }\n\n private void initializeUIComponents() {\n toolbar = findViewById(R.id.toolbar);\n setSupportActionBar(toolbar);\n\n cameraPreviewBroadcast = findViewById(R.id.camera_preview_broadcast);\n textAiStatusMessage = findViewById(R.id.text_ai_status_message);\n toggleAiTrackingGroup = findViewById(R.id.toggle_ai_tracking_group);\n btnToggleBallTracking = findViewById(R.id.btn_toggle_ball_tracking);\n btnTogglePlayerTracking = findViewById(R.id.btn_toggle_player_tracking);\n btnTogglePoseEstimation = findViewById(R.id.btn_toggle_pose_estimation);\n buttonStartRecordingMain = findViewById(R.id.button_start_recording_main);\n buttonQuickWicketMain = findViewById(R.id.button_quick_wicket_main);\n fabMainAction = findViewById(R.id.fab_main_action);\n\n View scorePanel = findViewById(R.id.cricket_score_panel_broadcast);\n if (scorePanel == null) {\n Log.e(TAG, \"Cricket score panel (broadcast) not found in layout!\");\n }\n initializeCricketScorePanel();\n }\n\n private void setupButtonListeners() {\n if (buttonStartRecordingMain != null) {\n buttonStartRecordingMain.setOnClickListener(v -> {\n if (!isRecording) {\n startRecording();\n } else {\n stopRecording();\n }\n });\n }\n\n if (buttonQuickWicketMain != null) {\n buttonQuickWicketMain.setOnClickListener(v -> addWicket());\n }\n\n if (fabMainAction != null) {\n fabMainAction.setOnClickListener(view -> {\n Intent intent = new Intent(MainActivity.this, DashboardActivity.class);\n startActivity(intent);\n });\n }\n\n if (btnToggleBallTracking != null) {\n btnToggleBallTracking.setOnClickListener(v -> {\n isAiBallTrackingEnabled = !isAiBallTrackingEnabled;\n Log.d(TAG, \"Ball tracking toggled: \" + isAiBallTrackingEnabled);\n updateAiStatusDisplay();\n });\n }\n if (btnTogglePlayerTracking != null) {\n btnTogglePlayerTracking.setOnClickListener(v -> {\n isAiPlayerTrackingEnabled = !isAiPlayerTrackingEnabled;\n Log.d(TAG, \"Player tracking toggled: \" + isAiPlayerTrackingEnabled);\n updateAiStatusDisplay();\n });\n }\n if (btnTogglePoseEstimation != null) {\n btnTogglePoseEstimation.setOnClickListener(v -> {\n isAiPoseEstimationEnabled = !isAiPoseEstimationEnabled;\n Log.d(TAG, \"Pose estimation toggled: \" + isAiPoseEstimationEnabled);\n updateAiStatusDisplay();\n });\n }\n }\n\n private void updateAiStatusDisplay() {\n if (textAiStatusMessage == null) return;\n StringBuilder statusBuilder = new StringBuilder(\"AI: \");\n if (isAiBallTrackingEnabled) statusBuilder.append(\"Ball \");\n if (isAiPlayerTrackingEnabled) statusBuilder.append(\"Player \");\n if (isAiPoseEstimationEnabled) statusBuilder.append(\"Pose \");\n if (!isAiBallTrackingEnabled && !isAiPlayerTrackingEnabled && !isAiPoseEstimationEnabled) {\n statusBuilder.append(\"OFF\");\n } else {\n statusBuilder.append(\"ON\");\n }\n textAiStatusMessage.setText(statusBuilder.toString());\n Log.d(TAG, \"Updated AI Status Display: \" + statusBuilder.toString());\n }\n\n private void initializeCameraAndHelpers() {\n faceRecognitionHelper = new FaceRecognitionHelper(this);\n shirtNumberRecognitionHelper = new ShirtNumberRecognitionHelper(this);\n startCamera();\n }\n\n private boolean allPermissionsGranted() {\n for (String permission : REQUIRED_PERMISSIONS) {\n if (ContextCompat.checkSelfPermission(this, permission) != PackageManager.PERMISSION_GRANTED) {\n Log.d(TAG, \"Permission not granted: \" + permission);\n return false;\n }\n }\n Log.d(TAG, \"All permissions granted\");\n return true;\n }\n\n private void startCamera() {\n ListenableFuture<ProcessCameraProvider> cameraProviderFuture = ProcessCameraProvider.getInstance(this);\n cameraProviderFuture.addListener(() -> {\n try {\n cameraProvider = cameraProviderFuture.get();\n bindCameraPreview();\n } catch (ExecutionException | InterruptedException e) {\n Log.e(TAG, \"Error starting camera: \" + e.getMessage());\n }\n }, ContextCompat.getMainExecutor(this));\n }\n\n private void bindCameraPreview() {\n if (cameraProvider == null) {\n Log.e(TAG, \"Camera provider is null\");\n Toast.makeText(this, \"Failed to initialize camera. Please restart the app.\", Toast.LENGTH_LONG).show();\n return;\n }\n try {\n cameraProvider.unbindAll();\n preview = new Preview.Builder().build();\n imageAnalysis = new ImageAnalysis.Builder()\n .setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST)\n .build();\n imageAnalysis.setAnalyzer(ContextCompat.getMainExecutor(this), this::analyzeImage);\n CameraSelector cameraSelector = CameraSelector.DEFAULT_BACK_CAMERA;\n Recorder recorder = new Recorder.Builder()\n .setQualitySelector(QualitySelector.from(Quality.HIGHEST))\n .build();\n videoCapture = VideoCapture.withOutput(recorder);\n camera = cameraProvider.bindToLifecycle(this, cameraSelector, preview, imageAnalysis, videoCapture);\n if (cameraPreviewBroadcast != null) {\n preview.setSurfaceProvider(cameraPreviewBroadcast.getSurfaceProvider());\n } else {\n Log.e(TAG, \"cameraPreviewBroadcast is null!\");\n }\n } catch (Exception e) {\n Log.e(TAG, \"Error binding camera preview: \" + e.getMessage(), e);\n try { \n cameraProvider.unbindAll();\n preview = new Preview.Builder().build(); \n imageAnalysis = new ImageAnalysis.Builder()\n .setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST)\n .build();\n imageAnalysis.setAnalyzer(ContextCompat.getMainExecutor(this), this::analyzeImage);\n camera = cameraProvider.bindToLifecycle(this, CameraSelector.DEFAULT_BACK_CAMERA, preview, imageAnalysis);\n if (cameraPreviewBroadcast != null) {\n preview.setSurfaceProvider(cameraPreviewBroadcast.getSurfaceProvider());\n }\n Toast.makeText(this, \"Video recording may not be available\", Toast.LENGTH_SHORT).show();\n } catch (Exception fallbackError) {\n Log.e(TAG, \"Fallback camera binding also failed: \" + fallbackError.getMessage());\n }\n }\n }\n\n @ExperimentalGetImage\n private void analyzeImage(ImageProxy imageProxy) {\n if (!isAiBallTrackingEnabled && !isAiPlayerTrackingEnabled && !isAiPoseEstimationEnabled) {\n imageProxy.close();\n return;\n }\n try {\n Bitmap bitmap = ImageUtils.imageProxyToBitmap(imageProxy); \n if (bitmap == null) {\n imageProxy.close();\n return;\n }\n if (isAiPlayerTrackingEnabled || isAiPoseEstimationEnabled) {\n if (faceRecognitionHelper != null) {\n faceRecognitionHelper.detectFaces(bitmap, new FaceRecognitionHelper.FaceDetectionCallback() {\n @Override\n public void onFacesDetected(@NonNull List<com.google.mlkit.vision.face.Face> faces) {\n if (!faces.isEmpty()) {\n Log.d(TAG, \"Face detected: \" + faces.size());\n // TODO: Process faces for player ID or pose\n }\n }\n @Override\n public void onFailure(@NonNull Exception e) { Log.e(TAG, \"Face detection error\", e); }\n });\n }\n if (shirtNumberRecognitionHelper != null) {\n Bitmap shirtBitmap = bitmap.copy(bitmap.getConfig(), true);\n shirtNumberRecognitionHelper.recognizeShirtNumber(shirtBitmap, new ShirtNumberRecognitionHelper.ShirtNumberRecognitionCallback() {\n @Override\n public void onShirtNumberRecognized(String shirtNumber) {\n if (!shirtNumber.isEmpty()) {\n Log.d(TAG, \"Shirt #\" + shirtNumber + \" recognized\");\n // TODO: Process shirt number for player ID\n }\n }\n @Override\n public void onFailure(@NonNull Exception e) { Log.e(TAG, \"Shirt number recognition error\", e); }\n });\n }\n }\n // TODO: Implement ball tracking if isAiBallTrackingEnabled\n // TODO: Implement pose estimation if isAiPoseEstimationEnabled (if not covered by face/general player tracking)\n\n } catch (Exception e) {\n Log.e(TAG, \"Error in image analysis\", e);\n } finally {\n imageProxy.close();\n }\n }\n\n private void startRecording() {\n if (videoCapture == null) {\n Toast.makeText(this, \"VideoCapture not initialized\", Toast.LENGTH_SHORT).show();\n return;\n }\n if (isRecording) {\n Toast.makeText(this, \"Already recording\", Toast.LENGTH_SHORT).show();\n return;\n }\n File videoDir = new File(getExternalFilesDir(null), \"CricketVideos\"); \n if (!videoDir.exists() && !videoDir.mkdirs()) {\n Log.e(TAG, \"Failed to create directory for videos\");\n return;\n }\n File videoFile = new File(videoDir, new SimpleDateFormat(\"yyyyMMdd_HHmmss\", Locale.US).format(System.currentTimeMillis()) + \".mp4\");\n FileOutputOptions outputOptions = new FileOutputOptions.Builder(videoFile).build();\n\n try {\n androidx.camera.video.PendingRecording pendingRecording = videoCapture.getOutput().prepareRecording(this, outputOptions);\n if (ContextCompat.checkSelfPermission(this, Manifest.permission.RECORD_AUDIO) == PackageManager.PERMISSION_GRANTED) {\n pendingRecording.withAudioEnabled();\n } else {\n Log.w(TAG, \"Record audio permission not granted, recording without audio.\");\n }\n recording = pendingRecording.start(ContextCompat.getMainExecutor(this), videoRecordEvent -> {\n if (videoRecordEvent instanceof VideoRecordEvent.Start) {\n isRecording = true;\n if (buttonStartRecordingMain != null) {\n buttonStartRecordingMain.setText(\"Stop Recording\");\n }\n } else if (videoRecordEvent instanceof VideoRecordEvent.Finalize) {\n VideoRecordEvent.Finalize finalizeEvent = (VideoRecordEvent.Finalize) videoRecordEvent;\n if (!finalizeEvent.hasError()) {\n String message = \"Video saved: \" + videoFile.getAbsolutePath();\n Toast.makeText(MainActivity.this, message, Toast.LENGTH_SHORT).show();\n } else {\n if(recording != null) recording.close(); \n recording = null;\n String message = \"Video capture failed: \" + finalizeEvent.getError();\n Toast.makeText(MainActivity.this, message, Toast.LENGTH_SHORT).show();\n }\n isRecording = false;\n if (buttonStartRecordingMain != null) {\n buttonStartRecordingMain.setText(\"Record\");\n }\n }\n });\n Toast.makeText(this, \"Recording started\", Toast.LENGTH_SHORT).show();\n } catch (Exception e) {\n Log.e(TAG, \"Error starting recording\", e);\n }\n }\n\n private void stopRecording() {\n if (recording != null) {\n recording.stop();\n recording = null;\n isRecording = false;\n Toast.makeText(this, \"Recording stopped\", Toast.LENGTH_SHORT).show();\n if (buttonStartRecordingMain != null) {\n buttonStartRecordingMain.setText(\"Record\");\n }\n }\n }\n\n private void setupFirebase() {\n try {\n FirebaseDatabase.getInstance().setPersistenceEnabled(true);\n FirebaseDatabase.getInstance().getReference().keepSynced(true);\n Log.d(TAG, \"Firebase initialized with offline persistence\");\n } catch (Exception e) {\n Log.e(TAG, \"Firebase persistence error: \" + e.getMessage());\n }\n }\n\n private void resetMatchData() {\n if (cricketMatchService != null) {\n cricketMatchService.resetMatch(); \n currentMatch = null; \n }\n initializeCricketScorePanel();\n Toast.makeText(this, \"Match data reset\", Toast.LENGTH_SHORT).show();\n }\n\n private void initializeCricketScorePanel() {\n if (cricketMatchService == null) {\n cricketMatchService = CricketMatchService.getInstance(this);\n }\n currentMatch = cricketMatchService.getCurrentMatch();\n if (currentMatch == null) {\n currentMatch = cricketMatchService.createMatch(\"SPU\", \"Opponent XI\", 20); \n Log.d(TAG, \"New match created in initializeCricketScorePanel\");\n }\n updateCricketUIFromModel(); \n }\n\n\n private void setupBatsmenInfo(String name1, String name2, int score1, int score2, int balls1, int balls2) {\n TextView textBatsman1Name = findViewById(R.id.text_batsman1_on_strike_simplified);\n TextView textBatsman2Name = findViewById(R.id.text_batsman2_simplified);\n TextView textBatsman1Score = findViewById(R.id.text_batsman1_score_simplified);\n TextView textBatsman2Score = findViewById(R.id.text_batsman2_score_simplified);\n\n if (textBatsman1Name != null) textBatsman1Name.setText(name1 + (balls1 > 0 || score1 > 0 ? \"*\" : \"\"));\n if (textBatsman2Name != null) textBatsman2Name.setText(name2);\n if (textBatsman1Score != null) textBatsman1Score.setText(String.format(Locale.getDefault(), \"%d (%d)\", score1, balls1));\n if (textBatsman2Score != null) textBatsman2Score.setText(String.format(Locale.getDefault(), \"%d (%d)\", score2, balls2));\n }\n\n private void setupBowlerInfo(String name, int wickets, int runs, int overs, int ballsInOver) {\n TextView textBowlerName = findViewById(R.id.text_bowler_name_simplified);\n TextView textBowlerFigures = findViewById(R.id.text_bowler_figures_simplified);\n\n if (textBowlerName != null) textBowlerName.setText(name);\n if (textBowlerFigures != null) {\n textBowlerFigures.setText(String.format(Locale.getDefault(), \"%d-%d (%d.%d)\", wickets, runs, overs, ballsInOver));\n }\n }\n \n private void updateThisOverDisplay(Innings innings) {\n TextView textThisOver = findViewById(R.id.text_this_over_simplified);\n if (textThisOver != null && innings != null && innings.getCurrentOver() != null) {\n Over currentOverObj = innings.getCurrentOver();\n StringBuilder overSummary = new StringBuilder(\"This Over: \");\n List<Ball> ballsInOverList = currentOverObj.getBalls(); \n for (int i = 0; i < ballsInOverList.size(); i++) {\n Ball ball = ballsInOverList.get(i);\n if (ball.isWicket()) overSummary.append(\"W \");\n else if (ball.isExtra()) {\n if (ball.getBallType() == Ball.BallType.WIDE) overSummary.append(\"Wd \");\n else if (ball.getBallType() == Ball.BallType.NO_BALL) {\n overSummary.append(ball.getRunsScored() > 0 ? (ball.getRunsScored() - 1) + \"Nb \" : \"Nb \");\n } else if (ball.getBallType() == Ball.BallType.BYE) {\n overSummary.append(ball.getRunsScored()).append(\"B \");\n } else if (ball.getBallType() == Ball.BallType.LEG_BYE) {\n overSummary.append(ball.getRunsScored()).append(\"Lb \");\n }\n } else if (ball.getRunsScored() == 0) overSummary.append(\"• \");\n else overSummary.append(ball.getRunsScored()).append(\" \");\n }\n textThisOver.setText(overSummary.toString().trim());\n } else if (textThisOver != null) {\n textThisOver.setText(\"This Over: \");\n }\n }\n\n\n private void updateCricketUIFromModel() {\n if (currentMatch == null) {\n Log.d(TAG, \"updateCricketUIFromModel: currentMatch is null. Initializing panel.\");\n initializeCricketScorePanel(); \n if (currentMatch == null) { \n Log.e(TAG, \"Failed to initialize or get currentMatch in updateCricketUIFromModel.\");\n return; \n }\n }\n\n Innings innings = currentMatch.getCurrentInnings();\n if (innings == null) {\n Log.e(TAG, \"updateCricketUIFromModel: currentInnings is null for match \" + (currentMatch != null ? currentMatch.getMatchName() : \"Unknown Match\"));\n teamBattingName = currentMatch.getTeamBatting() != null ? currentMatch.getTeamBatting().getTeamName() : \"Team A\";\n currentDisplayedScore = 0;\n currentDisplayedWickets = 0;\n currentDisplayedOversCompleted = 0;\n currentDisplayedBallsInOver = 0;\n batsman1DisplayNome = \"Striker\";\n batsman1DisplayScore = 0;\n batsman1DisplayBalls = 0;\n batsman2DisplayNome = \"Non-Striker\";\n batsman2DisplayScore = 0;\n batsman2DisplayBalls = 0;\n bowlerDisplayName = \"Bowler\";\n bowlerDisplayWickets = 0;\n bowlerDisplayRuns = 0;\n bowlerDisplayOvers = 0;\n bowlerDisplayBallsInOver = 0;\n } else {\n teamBattingName = currentMatch.getTeamBatting() != null ? currentMatch.getTeamBatting().getTeamName() : \"Team A\"; \n currentDisplayedScore = innings.getTotalScore();\n currentDisplayedWickets = innings.getWickets();\n float totalOversFloat = innings.getTotalOvers();\n currentDisplayedOversCompleted = (int) totalOversFloat;\n currentDisplayedBallsInOver = (int) Math.round((totalOversFloat - currentDisplayedOversCompleted) * 100.0) / 10; \n if (currentDisplayedBallsInOver >=6) { \n currentDisplayedOversCompleted += currentDisplayedBallsInOver / 6;\n currentDisplayedBallsInOver = currentDisplayedBallsInOver % 6;\n }\n\n Player striker = innings.getStriker();\n Player nonStriker = innings.getNonStriker();\n batsman1DisplayNome = (striker != null) ? striker.getName() : \"Striker\";\n batsman1DisplayScore = (striker != null && striker.getBattingStats() != null) ? striker.getBattingStats().getRuns() : 0;\n batsman1DisplayBalls = (striker != null && striker.getBattingStats() != null) ? striker.getBattingStats().getBallsFaced() : 0;\n batsman2DisplayNome = (nonStriker != null) ? nonStriker.getName() : \"Non-Striker\";\n batsman2DisplayScore = (nonStriker != null && nonStriker.getBattingStats() != null) ? nonStriker.getBattingStats().getRuns() : 0;\n batsman2DisplayBalls = (nonStriker != null && nonStriker.getBattingStats() != null) ? nonStriker.getBattingStats().getBallsFaced() : 0;\n\n Player bowler = innings.getCurrentBowler();\n if (bowler != null && bowler.getBowlingStats() != null) {\n bowlerDisplayName = bowler.getName();\n bowlerDisplayWickets = bowler.getBowlingStats().getWickets();\n bowlerDisplayRuns = bowler.getBowlingStats().getRunsConceded();\n bowlerDisplayOvers = bowler.getBowlingStats().getOvers(); \n bowlerDisplayBallsInOver = bowler.getBowlingStats().getBallsInCurrentOver();\n } else {\n bowlerDisplayName = \"Bowler\";\n bowlerDisplayWickets = 0;\n bowlerDisplayRuns = 0;\n bowlerDisplayOvers = 0;\n bowlerDisplayBallsInOver = 0;\n }\n updateThisOverDisplay(innings); \n }\n \n setupBatsmenInfo(batsman1DisplayNome, batsman2DisplayNome, batsman1DisplayScore, batsman2DisplayScore, batsman1DisplayBalls, batsman2DisplayBalls);\n setupBowlerInfo(bowlerDisplayName, bowlerDisplayWickets, bowlerDisplayRuns, bowlerDisplayOvers, bowlerDisplayBallsInOver);\n \n TextView textTeamBattingView = findViewById(R.id.text_team_batting_name_simplified);\n TextView textScoreView = findViewById(R.id.text_team_score_simplified);\n TextView textOversView = findViewById(R.id.text_overs_simplified);\n TextView textTargetView = findViewById(R.id.text_target_simplified);\n\n if (textTeamBattingView != null) textTeamBattingView.setText(teamBattingName.toUpperCase());\n if (textScoreView != null) textScoreView.setText(String.format(Locale.getDefault(), \"%d-%d\", currentDisplayedScore, currentDisplayedWickets));\n if (textOversView != null) textOversView.setText(String.format(Locale.getDefault(), \"(%d.%d)\", currentDisplayedOversCompleted, currentDisplayedBallsInOver));\n \n if (textTargetView != null && currentMatch != null) { \n int matchTarget = currentMatch.getTargetScore(); \n if (matchTarget > 0 && currentMatch.getInnings().size() > 1) { \n textTargetView.setText(String.format(Locale.getDefault(),\"TGT %d\", matchTarget));\n textTargetView.setVisibility(View.VISIBLE);\n } else {\n textTargetView.setVisibility(View.GONE);\n }\n }\n }\n\n private void addWicket() { \n if (currentMatch != null && cricketMatchService != null) {\n cricketMatchService.addWicket(); \n updateCricketUIFromModel(); \n // Toast.makeText(this, \"Wicket recorded\", Toast.LENGTH_SHORT).show(); // Already shown by button listener\n } else {\n Toast.makeText(this, \"Match not initialized for wicket\", Toast.LENGTH_SHORT).show();\n }\n }\n\n private void resetCricketScorePanel() {\n initializeCricketScorePanel(); \n }\n\n @Override\n public boolean onCreateOptionsMenu(Menu menu) {\n getMenuInflater().inflate(R.menu.main_menu, menu);\n return true;\n }\n\n @Override\n public boolean onOptionsItemSelected(MenuItem item) {\n int id = item.getItemId();\n if (id == R.id.action_reset) {\n resetMatchData(); \n return true;\n } else if (id == R.id.action_settings) {\n Toast.makeText(this, \"Settings (Not Implemented)\", Toast.LENGTH_SHORT).show();\n return true;\n } else if (id == R.id.action_dashboard) {\n Intent intent = new Intent(this, DashboardActivity.class);\n startActivity(intent);\n return true;\n }\n return super.onOptionsItemSelected(item);\n }\n\n @Override\n public void onRequestPermissionsResult(int requestCode, @NonNull String[] permissions, @NonNull int[] grantResults) {\n super.onRequestPermissionsResult(requestCode, permissions, grantResults);\n if (requestCode == REQUEST_CODE_PERMISSIONS) {\n boolean allGranted = true;\n for (int result : grantResults) {\n if (result != PackageManager.PERMISSION_GRANTED) {\n allGranted = false;\n break;\n }\n }\n if (allGranted) {\n Log.d(TAG, \"All permissions granted in onRequestPermissionsResult\");\n checkPermissionsAndInitialize();\n } else {\n boolean shouldShowRationale = false;\n for (String permission : REQUIRED_PERMISSIONS) {\n if (ActivityCompat.shouldShowRequestPermissionRationale(this, permission)) {\n shouldShowRationale = true;\n break;\n }\n }\n if (shouldShowRationale) {\n new AlertDialog.Builder(this)\n .setTitle(\"Permissions Required\")\n .setMessage(\"This app needs camera and recording permissions to function properly.\")\n .setPositiveButton(\"Grant Permissions\", (dialog, which) -> \n ActivityCompat.requestPermissions(MainActivity.this, REQUIRED_PERMISSIONS, REQUEST_CODE_PERMISSIONS)\n )\n .setNegativeButton(\"Exit\", (dialog, 