 @Override
 public boolean onCreateOptionsMenu(Menu menu) {
 getMenuInflater().inflate(R.menu.main_menu, menu);
 menu.add(Menu.NONE, 1001, Menu.NONE, "Register Player Faces");
 menu.add(Menu.NONE, 1002, Menu.NONE, "Register Players (Alt)");
