 if (faceRecognitionHelper != null) {
 faceRecognitionHelper.close();
 }
 if (shirtNumberRecognitionHelper != null) {
 shirtNumberRecognitionHelper.close();
 }
 if (isRecording) {
 stopRecording();
 }
 }
