 private void startRecording() {
 if (videoCapture == null) {
 Toast.makeText(this, "VideoCapture not initialized", Toast.LENGTH_SHORT).show();
 return;
 }
 if (isRecording) {
 Toast.makeText(this, "Already recording", Toast.LENGTH_SHORT).show();
 return;
 }
 File videoDir = new File(getExternalFilesDir(null), "CricketVideos"); 
 if (!videoDir.exists() && !videoDir.mkdirs()) {
 Log.e(TAG, "Failed to create directory for videos");
 return;
 }
 String videoFileName = new SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US).format(System.currentTimeMillis()) + ".mp4";
 File videoFile = new File(videoDir, videoFileName);
 FileOutputOptions outputOptions = new FileOutputOptions.Builder(videoFile).build();

 try {
 androidx.camera.video.PendingRecording pendingRecording = videoCapture.getOutput().prepareRecording(this, outputOptions);
 if (ContextCompat.checkSelfPermission(this, Manifest.permission.RECORD_AUDIO) == PackageManager.PERMISSION_GRANTED) {
 pendingRecording.withAudioEnabled();
 } else {
 Log.w(TAG, "Record audio permission not granted, recording without audio.");
 }
 recording = pendingRecording.start(ContextCompat.getMainExecutor(this), videoRecordEvent -> {
 if (videoRecordEvent instanceof VideoRecordEvent.Start) {
 isRecording = true;
 if (buttonStartRecordingMain != null) {
 buttonStartRecordingMain.setText("Stop Recording");
 }
 } else if (videoRecordEvent instanceof VideoRecordEvent.Finalize) {
 VideoRecordEvent.Finalize finalizeEvent = (VideoRecordEvent.Finalize) videoRecordEvent;
 if (!finalizeEvent.hasError()) {
 String message = "Video saved: " + videoFile.getAbsolutePath();
 Toast.makeText(MainActivity.this, message, Toast.LENGTH_SHORT).show();
 Log.d(TAG, message);
 uploadVideoToFirebase(videoFile, videoFileName); // Upload after local save
 } else {
 if(recording != null) recording.close(); 
 recording = null;
 String message = "Video capture failed: " + finalizeEvent.getError();
 Toast.makeText(MainActivity.this, message, Toast.LENGTH_SHORT).show();
 Log.e(TAG, message);
 }
 isRecording = false;
 if (buttonStartRecordingMain != null) {
 buttonStartRecordingMain.setText("Record");
 }
 }
 });
 Toast.makeText(this, "Recording started", Toast.LENGTH_SHORT).show();
 } catch (Exception e) {
 Log.e(TAG, "Error starting recording", e);
 }
 }

 private void uploadVideoToFirebase(File videoFile, String videoFileName) {
 if (currentMatch == null || currentMatch.getId() == null) {
 Log.e(TAG, "Cannot upload video: currentMatch or matchId is null.");
 Toast.makeText(this, "Error: Match details not available for video upload.", Toast.LENGTH_SHORT).show();
 return;
 }
 String matchId = currentMatch.getId();
 String recordingId = UUID.randomUUID().toString();
 StorageReference storageRef = FirebaseStorage.getInstance().getReference();
 StorageReference videoStorageRef = storageRef.child("videos/" + matchId + "/" + recordingId + "_" + videoFileName);

 UploadTask uploadTask = videoStorageRef.putFile(Uri.fromFile(videoFile));

 Toast.makeText(this, "Uploading video...", Toast.LENGTH_SHORT).show();

 uploadTask.addOnSuccessListener(taskSnapshot -> videoStorageRef.getDownloadUrl().addOnSuccessListener(downloadUri -> {
 String downloadUrl = downloadUri.toString();
 Log.d(TAG, "Video uploaded successfully. URL: " + downloadUrl);
 Toast.makeText(MainActivity.this, "Video uploaded!", Toast.LENGTH_SHORT).show();

 DatabaseReference dbRef = FirebaseDatabase.getInstance().getReference("recordings").child(matchId).child(recordingId);
 Map<String, Object> recordingData = new HashMap<>();
 recordingData.put("fileName", videoFileName);
 recordingData.put("storagePath", videoStorageRef.getPath());
 recordingData.put("downloadUrl", downloadUrl);
 recordingData.put("timestamp", System.currentTimeMillis());

 dbRef.setValue(recordingData)
 .addOnSuccessListener(aVoid -> Log.d(TAG, "Recording metadata saved to RTDB."))
 .addOnFailureListener(e -> Log.e(TAG, "Failed to save recording metadata to RTDB.", e));

 }).addOnFailureListener(e -> {
 Log.e(TAG, "Failed to get download URL.", e);
 Toast.makeText(MainActivity.this, "Upload complete, but failed to get URL.", Toast.LENGTH_SHORT).show();
 })).addOnFailureListener(e -> {
 Log.e(TAG, "Video upload failed.", e);
 Toast.makeText(MainActivity.this, "Video upload failed: " + e.getMessage(), Toast.LENGTH_LONG).show();
 }).addOnProgressListener(snapshot -> {
 double progress = (100.0 * snapshot.getBytesTransferred()) / snapshot.getTotalByteCount();
 Log.d(TAG, "Upload is " + progress + "% done");
 });
 }


 private void stopRecording() {
 if (recording != null) {
 recording.stop(); 
 }
 }

 private void setupFirebase() {
 try {
 FirebaseDatabase.getInstance().setPersistenceEnabled(true);
 FirebaseDatabase.getInstance().getReference().keepSynced(true);
 Log.d(TAG, "Firebase initialized with offline persistence");
 } catch (Exception e) {
 Log.e(TAG, "Firebase persistence error: " + e.getMessage());
 }
 }

 private void resetMatchData() {
 if (cricketMatchService != null) {
 cricketMatchService.resetMatch(); 
 currentMatch = null; 
 }
 initializeCricketScorePanel();
 Toast.makeText(this, "Match data reset", Toast.LENGTH_SHORT).show();
 }

 private void initializeCricketScorePanel() {
 if (cricketMatchService == null) {
 cricketMatchService = CricketMatchService.getInstance(this);
 }
 currentMatch = cricketMatchService.getCurrentMatch();
 if (currentMatch == null) {
 currentMatch = cricketMatchService.createMatch("SPU", "Opponent XI", 20); 
 Log.d(TAG, "New match created in initializeCricketScorePanel");
 }
 updateCricketUIFromModel(); 
 }


 private void setupBatsmenInfo(String name1, String name2, int score1, int score2, int balls1, int balls2) {
 TextView textBatsman1Name = findViewById(R.id.text_batsman1_on_strike_simplified);
 TextView textBatsman2Name = findViewById(R.id.text_batsman2_simplified);
 TextView textBatsman1Score = findViewById(R.id.text_batsman1_score_simplified);
 TextView textBatsman2Score = findViewById(R.id.text_batsman2_score_simplified);

 if (textBatsman1Name != null) textBatsman1Name.setText(name1 + (balls1 > 0 || score1 > 0 ? "*" : ""));
 if (textBatsman2Name != null) textBatsman2Name.setText(name2);
 if (textBatsman1Score != null) textBatsman1Score.setText(String.format(Locale.getDefault(), "%d (%d)", score1, balls1));
 if (textBatsman2Score != null) textBatsman2Score.setText(String.format(Locale.getDefault(), "%d (%d)", score2, balls2));
 }

 private void setupBowlerInfo(String name, int wickets, int runs, int overs, int ballsInOver) {
 TextView textBowlerName = findViewById(R.id.text_bowler_name_simplified);
 TextView textBowlerFigures = findViewById(R.id.text_bowler_figures_simplified);

 if (textBowlerName != null) textBowlerName.setText(name);
 if (textBowlerFigures != null) {
 textBowlerFigures.setText(String.format(Locale.getDefault(), "%d-%d (%d.%d)", wickets, runs, overs, ballsInOver));
 }
 }

 private void updateThisOverDisplay(Innings innings) {
 TextView textThisOver = findViewById(R.id.text_this_over_simplified);
 if (textThisOver != null && innings != null && innings.getCurrentOver() != null) {
 Over currentOverObj = innings.getCurrentOver();
 StringBuilder overSummary = new StringBuilder("This Over: ");
 List<Ball> ballsInOverList = currentOverObj.getBalls(); 
 for (int i = 0; i < ballsInOverList.size(); i++) {
 Ball ball = ballsInOverList.get(i);
 if (ball.isWicket()) overSummary.append("W ");
 else if (ball.isExtra()) {
 if (ball.getBallType() == Ball.BallType.WIDE) overSummary.append("Wd ");
 else if (ball.getBallType() == Ball.BallType.NO_BALL) {
 overSummary.append(ball.getRunsScored() > 0 ? (ball.getRunsScored() - 1) + "Nb " : "Nb ");
 } else if (ball.getBallType() == Ball.BallType.BYE) {
 overSummary.append(ball.getRunsScored()).append("B ");
 } else if (ball.getBallType() == Ball.BallType.LEG_BYE) {
 overSummary.append(ball.getRunsScored()).append("Lb ");
 }
 } else if (ball.getRunsScored() == 0) overSummary.append("• ");
 else overSummary.append(ball.getRunsScored()).append(" ");
 }
 textThisOver.setText(overSummary.toString().trim());
 } else if (textThisOver != null) {
 textThisOver.setText("This Over: ");
 }
 }


 private void updateCricketUIFromModel() {
 if (currentMatch == null) {
 Log.d(TAG, "updateCricketUIFromModel: currentMatch is null. Initializing panel.");
 initializeCricketScorePanel(); 
 if (currentMatch == null) { 
 Log.e(TAG, "Failed to initialize or get currentMatch in updateCricketUIFromModel.");
 return; 
 }
 }

 Innings innings = currentMatch.getCurrentInnings();
 if (innings == null) {
 Log.e(TAG, "updateCricketUIFromModel: currentInnings is null for match " + (currentMatch != null ? currentMatch.getMatchName() : "Unknown Match"));
 teamBattingName = currentMatch.getTeamBatting() != null ? currentMatch.getTeamBatting().getTeamName() : "Team A";
 currentDisplayedScore = 0;
 currentDisplayedWickets = 0;
 currentDisplayedOversCompleted = 0;
 currentDisplayedBallsInOver = 0;
 batsman1DisplayNome = "Striker";
 batsman1DisplayScore = 0;
 batsman1DisplayBalls = 0;
 batsman2DisplayNome = "Non-Striker";
 batsman2DisplayScore = 0;
 batsman2DisplayBalls = 0;
 bowlerDisplayName = "Bowler";
 bowlerDisplayWickets = 0;
 bowlerDisplayRuns = 0;
 bowlerDisplayOvers = 0;
 bowlerDisplayBallsInOver = 0;
 } else {
 teamBattingName = currentMatch.getTeamBatting() != null ? currentMatch.getTeamBatting().getTeamName() : "Team A"; 
 currentDisplayedScore = innings.getTotalScore();
 currentDisplayedWickets = innings.getWickets();
 float totalOversFloat = innings.getTotalOvers();
 currentDisplayedOversCompleted = (int) totalOversFloat;
 currentDisplayedBallsInOver = (int) Math.round((totalOversFloat - currentDisplayedOversCompleted) * 100.0) / 10; 
 if (currentDisplayedBallsInOver >=6) { 
 currentDisplayedOversCompleted += currentDisplayedBallsInOver / 6;
 currentDisplayedBallsInOver = currentDisplayedBallsInOver % 6;
 }

 Player striker = innings.getStriker();
 Player nonStriker = innings.getNonStriker();
 batsman1DisplayNome = (striker != null) ? striker.getName() : "Striker";
 batsman1DisplayScore = (striker != null && striker.getBattingStats() != null) ? striker.getBattingStats().getRuns() : 0;
 batsman1DisplayBalls = (striker != null && striker.getBattingStats() != null) ? striker.getBattingStats().getBallsFaced() : 0;
 batsman2DisplayNome = (nonStriker != null) ? nonStriker.getName() : "Non-Striker";
 batsman2DisplayScore = (nonStriker != null && nonStriker.getBattingStats() != null) ? nonStriker.getBattingStats().getRuns() : 0;
 batsman2DisplayBalls = (nonStriker != null && nonStriker.getBattingStats() != null) ? nonStriker.getBattingStats().getBallsFaced() : 0;

 Player bowler = innings.getCurrentBowler();
 if (bowler != null && bowler.getBowlingStats() != null) {
 bowlerDisplayName = bowler.getName();
 bowlerDisplayWickets = bowler.getBowlingStats().getWickets();
 bowlerDisplayRuns = bowler.getBowlingStats().getRunsConceded();
 bowlerDisplayOvers = bowler.getBowlingStats().getOvers(); 
 bowlerDisplayBallsInOver = bowler.getBowlingStats().getBallsInCurrentOver();
 } else {
 bowlerDisplayName = "Bowler";
 bowlerDisplayWickets = 0;
 bowlerDisplayRuns = 0;
 bowlerDisplayOvers = 0;
 bowlerDisplayBallsInOver = 0;
 }
 updateThisOverDisplay(innings); 
 }

 setupBatsmenInfo(batsman1DisplayNome, batsman2DisplayNome, batsman1DisplayScore, batsman2DisplayScore, batsman1DisplayBalls, batsman2DisplayBalls);
 setupBowlerInfo(bowlerDisplayName, bowlerDisplayWickets, bowlerDisplayRuns, bowlerDisplayOvers, bowlerDisplayBallsInOver);

 TextView textTeamBattingView = findViewById(R.id.text_team_batting_name_simplified);
 TextView textScoreView = findViewById(R.id.text_team_score_simplified);
 TextView textOversView = findViewById(R.id.text_overs_simplified);
 TextView textTargetView = findViewById(R.id.text_target_simplified);

 if (textTeamBattingView != null) textTeamBattingView.setText(teamBattingName.toUpperCase());
 if (textScoreView != null) textScoreView.setText(String.format(Locale.getDefault(), \"%d-%d\", currentDisplayedScore, currentDisplayedWickets));
 if (textOversView != null) textOversView.setText(String.format(Locale.getDefault(), \"(%d.%d)\", currentDisplayedOversCompleted, currentDisplayedBallsInOver));\n \n if (textTargetView != null && currentMatch != null) { \n int matchTarget = currentMatch.getTargetScore(); \n if (matchTarget > 0 && currentMatch.getInnings().size() > 1) { \n textTargetView.setText(String.format(Locale.getDefault(),\"TGT %d\", matchTarget));\n textTargetView.setVisibility(View.VISIBLE);\n } else {\n textTargetView.setVisibility(View.GONE);\n }\n }\n }\n\n private void addWicket() { \n if (currentMatch != null && cricketMatchService != null) {\n cricketMatchService.addWicket(); \n updateCricketUIFromModel(); \n Toast.makeText(this, \"Wicket recorded!\", Toast.LENGTH_SHORT).show(); // Moved from listener for clarity\n } else {\n Toast.makeText(this, \"Match not initialized for wicket\", Toast.LENGTH_SHORT).show();\n }\n }\n\n private void resetCricketScorePanel() {\n initializeCricketScorePanel(); \n }\n\n @Override\n public boolean onCreateOptionsMenu(Menu menu) {\n getMenuInflater().inflate(R.menu.main_menu, menu);\n return true;\n }\n\n @Override\n public boolean onOptionsItemSelected(MenuItem item) {\n int id = item.getItemId();\n if (id == R.id.action_reset) {\n resetMatchData(); \n return true;\n } else if (id == R.id.action_settings) {\n Toast.makeText(this, \"Settings (Not Implemented)\", Toast.LENGTH_SHORT).show();\n return true;\n } else if (id == R.id.action_dashboard) {\n Intent intent = new Intent(this, DashboardActivity.class);\n startActivity(intent);\n return true;\n }\n return super.onOptionsItemSelected(item);\n }\n\n @Override\n public void onRequestPermissionsResult(int requestCode, @NonNull String[] permissions, @NonNull int[] grantResults) {\n super.onRequestPermissionsResult(requestCode, permissions, grantResults);\n if (requestCode == REQUEST_CODE_PERMISSIONS) {\n boolean allGranted = true;\n for (int result : grantResults) {\n if (result != PackageManager.PERMISSION_GRANTED) {\n allGranted = false;\n break;\n }\n }\n if (allGranted) {\n Log.d(TAG, \"All permissions granted in onRequestPermissionsResult\");\n checkPermissionsAndInitialize();\n } else {\n boolean shouldShowRationale = false;\n for (String permission : REQUIRED_PERMISSIONS) {\n if (ActivityCompat.shouldShowRequestPermissionRationale(this, permission)) {\n shouldShowRationale = true;\n break;\n }\n }\n if (shouldShowRationale) {\n new AlertDialog.Builder(this)\n .setTitle(\"Permissions Required\")\n .setMessage(\"This app needs camera and recording permissions to function properly.\")\n .setPositiveButton(\"Grant Permissions\", (dialog, which) -> \n ActivityCompat.requestPermissions(MainActivity.this, REQUIRED_PERMISSIONS, REQUEST_CODE_PERMISSIONS)\n )\n .setNegativeButton(\"Exit\", (dialog, which) -> finish())\n .setCancelable(false)\n .show();\n } else {\n Toast.makeText(this, R.string.permissions_not_granted, Toast.LENGTH_SHORT).show();\n new AlertDialog.Builder(this)\n .setTitle(\"Permissions Required\")\n .setMessage(\"This app needs camera and storage permissions. Please grant them in app settings.\")\n .setPositiveButton(\"Settings\", (dialog, which) -> {\n Intent intent = new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS);\n intent.setData(Uri.parse(\"package:\" + getPackageName()));\n startActivity(intent);\n finish();\n })\n .setNegativeButton(\"Exit\", (dialog, which) -> finish())\n .setCancelable(false)\n .show();\n }\n }\n }\n }\n\n @Override\n protected void onResume() {\n super.onResume();\n if (!isInitialized && allPermissionsGranted()) {\n initializeCameraAndHelpers(); \n isInitialized = true;\n }\n if (cricketMatchService != null) { \n currentMatch = cricketMatchService.getCurrentMatch(); \n updateCricketUIFromModel();\n } else {\n Log.e(TAG, \"CricketMatchService is null in onResume\");\n initializeCricketScorePanel(); \n }\n }\n\n private void checkPermissionsAndInitialize() {\n if (allPermissionsGranted()) {\n if (!isInitialized) { \n initializeCameraAndHelpers();\n downloadFaceRecognitionModelIfNeeded(); \n isInitialized = true;\n }\n } else {\n ActivityCompat.requestPermissions(this, REQUIRED_PERMISSIONS, REQUEST_CODE_PERMISSIONS);\n }\n }\n\n private void downloadFaceRecognitionModelIfNeeded() { \n File modelFile = new File(getFilesDir(), \"facenet_mobile.tflite\");\n if (!modelFile.exists()) {\n new Thread(() -> {\n try {\n runOnUiThread(() -> {\n View rootView = findViewById(R.id.main_broadcast_layout); \n if (rootView != null) { \n Snackbar.make(rootView, \"Downloading face recognition model...\", Snackbar.LENGTH_LONG).show();\n } else {\n Toast.makeText(MainActivity.this, \"Downloading face recognition model...\", Toast.LENGTH_LONG).show();\n }\n });\n URL url = new URL(\"https://storage.googleapis.com/cricket-ai-models/facenet_mobile.tflite\"); \n HttpURLConnection connection = (HttpURLConnection) url.openConnection();\n connection.connect();\n if (connection.getResponseCode() != HttpURLConnection.HTTP_OK) {\n throw new IOException(\"HTTP error: \" + connection.getResponseCode() + \" - \" + connection.getResponseMessage());\n }\n InputStream input = connection.getInputStream();\n try (OutputStream output = new FileOutputStream(modelFile)) { \n byte[] buffer = new byte[4096];\n int bytesRead;\n while ((bytesRead = input.read(buffer)) != -1) {\n output.write(buffer, 0, bytesRead);\n }\n } finally {\n if (input != null) try { input.close(); } catch (IOException e) { Log.e(TAG, \"Error closing input stream\", e); } \n }\n runOnUiThread(() -> {\n View rootView = findViewById(R.id.main_broadcast_layout);\n if (rootView != null) {\n Snackbar.make(rootView, \"Face recognition model downloaded successfully\", Snackbar.LENGTH_SHORT).show();\n } else {\n Toast.makeText(MainActivity.this, \"Face recognition model downloaded successfully\", Toast.LENGTH_SHORT).show();\n }\n \n });\n } catch (Exception e) {\n Log.e(TAG, \"Model download failed\", e);\n runOnUiThread(() -> {\n View rootView = findViewById(R.id.main_broadcast_layout);\n if (rootView != null) {\n Snackbar.make(rootView, \"Failed to download model: \" + e.getMessage(), Snackbar.LENGTH_LONG).show();\n } else {\n Toast.makeText(MainActivity.this, \"Failed to download model: \" + e.getMessage(), Toast.LENGTH_LONG).show();\n }\n });\n }\n }).start();\n } else {\n Log.d(TAG, \"Face recognition model already exists.\");\n if (faceRecognitionHelper == null && isInitialized) { \n faceRecognitionHelper = new FaceRecognitionHelper(MainActivity.this);\n }\n }\n }\n\n @Override\n protected void onDestroy() {\n super.onDestroy();\n if (faceRecognitionHelper != null) {\n faceRecognitionHelper.close();\n }\n if (shirtNumberRecognitionHelper != null) {\n shirtNumberRecognitionHelper.close();\n }\n if (isRecording && recording != null) { \n recording.stop(); \n }\n if (cameraProvider != null) {\n cameraProvider.unbindAll(); \n }\n }\n}\n", instructions = "Further refactor MainActivity.java to resolve errors by: ensuring all UI component field declarations match their initialization in initializeUIComponents; correcting method calls for AI toggles and recording buttons; removing or commenting out all logic and fields related to the old UI (especially player name input, direct score manipulation, and old button listeners); ensuring score panel updates use IDs from cricket_score_panel_simplified.xml; and cleaning up any resulting unused variables or imports.", target_file = "app/src/main/java/com/finedine/spucricketclub/MainActivity.java"))"}]},{"role":"user","content":[{"type":"text","text":"<additional_data>
